/* Vertragswerk, Lexikon der Rechtsbegriffe: Daten und Aufbau des Reiters.
   Ein Eintrag: {id, wort, formen, kurz, bedeutung, abgrenzung: [{wort, id?, text}], quellen: [{t, url}]}.
   `formen` sind die Wortformen, die in Verträgen und Erläuterungen als Begriff markiert werden
   (Gross- und Kleinschreibung egal, nur ganze Wörter); `kurz` steht im Begriffskärtchen.
   Ein Verweis-Eintrag hat statt der Bedeutung `siehe` (id des geltenden Begriffs) und `text`. */
(function (G) {
  "use strict";
  var VW = G.VW = G.VW || {};

  VW.BEGRIFFE = [
    {id: "verleiher", wort: "Verleiher", formen: ["Verleiher", "Verleihers"], kurz: "Die Firma, die den Arbeitnehmer anstellt und ihn einem Einsatzbetrieb überlässt.", bedeutung: "Arbeitgeber, der einem Einsatzbetrieb Arbeitnehmer überlässt und ihm dabei wesentliche Weisungsbefugnisse gegenüber dem Arbeitnehmer abtritt. Er bleibt Arbeitgeber, auch während des Einsatzes. Wer gewerbsmässig verleiht, braucht eine Bewilligung des kantonalen Arbeitsamts, ausser er verleiht ausschliesslich den Inhaber oder die Mitbesitzer des Betriebs.", abgrenzung: [{wort: "Arbeitgeber", id: "arbeitgeber", text: "Jeder Verleiher ist Arbeitgeber, aber nicht jeder Arbeitgeber ist Verleiher; Verleiher ist nur, wer seine Arbeitnehmer einem Dritten zur Arbeit unter dessen Weisung überlässt."}, {wort: "Arbeitsvermittlung", id: "arbeitsvermittlung", text: "Der Vermittler führt Stellensuchende und Arbeitgeber zusammen und wird nicht selbst Arbeitgeber; der Verleiher stellt an und bleibt Arbeitgeber."}, {wort: "Einsatzbetrieb", id: "einsatzbetrieb", text: "Der Einsatzbetrieb erteilt die Weisungen bei der Arbeit, wird aber nicht Arbeitgeber."}], quellen: [{t: "Art. 12 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_12"}, {t: "Art. 26 Abs. 1 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_26"}, {t: "Art. 28 Abs. 2 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_28"}]},
    {id: "einsatzbetrieb", wort: "Einsatzbetrieb", formen: ["Einsatzbetrieb", "Einsatzbetriebs", "Einsatzbetriebes", "Einsatzbetriebe", "Einsatzbetrieben"], kurz: "Der Betrieb, dem der Verleiher den Arbeitnehmer überlässt und der ihm bei der Arbeit die Weisungen erteilt.", bedeutung: "Dritter, dem der Verleiher Arbeitnehmer überlässt. Er hat gegenüber dem Arbeitnehmer wesentliche Weisungsrechte sowie Überwachungs- und Sorgfaltspflichten, wird aber nicht sein Arbeitgeber. Mit dem Verleiher schliesst er den Verleihvertrag.", abgrenzung: [{wort: "Arbeitgeber", id: "arbeitgeber", text: "Arbeitgeber bleibt der Verleiher; der Einsatzbetrieb hat nur die Weisungsrechte während des Einsatzes."}, {wort: "Besteller, Auftraggeber", text: "Beim Werkvertrag oder Auftrag heisst die Gegenpartei Besteller oder Auftraggeber; sie erteilt keine Weisungen über die Ausführung der Arbeit im Einzelnen wie ein Einsatzbetrieb."}], quellen: [{t: "Art. 12 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_12"}, {t: "Art. 22 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.2.1"}]},
    {id: "arbeitnehmer", wort: "Arbeitnehmer", formen: ["Arbeitnehmer", "Arbeitnehmers", "verliehenen Arbeitnehmer", "verliehener Arbeitnehmer"], kurz: "Die Person, die im Dienst eines Arbeitgebers gegen Lohn arbeitet; im Verleih die Person, die dem Einsatzbetrieb überlassen wird.", bedeutung: "Wer sich durch Arbeitsvertrag verpflichtet, auf bestimmte oder unbestimmte Zeit Arbeit im Dienst eines Arbeitgebers zu leisten. Im Personalverleih ist es die Person, die der Verleiher anstellt und dem Einsatzbetrieb überlässt; sie arbeitet dort nach dessen Weisungen, bleibt aber Arbeitnehmer des Verleihers.", abgrenzung: [{wort: "Mitarbeiter", id: "mitarbeiter", text: "Die eigenen Angestellten des Einsatzbetriebs heissen im Vertragswerk Mitarbeiter, nie Arbeitnehmer."}, {wort: "Inhaber", id: "inhaber", text: "Im Selbstverleih ist der Arbeitnehmer zugleich Inhaber und Geschäftsführer des Verleihers; als Arbeitnehmer arbeitet er nach den Weisungen des Einsatzbetriebs."}], quellen: [{t: "Art. 319 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_319"}, {t: "Art. 12 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_12"}, {t: "Art. 19 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_19"}]},
    {id: "arbeitgeber", wort: "Arbeitgeber", formen: ["Arbeitgeber", "Arbeitgeberin", "Arbeitgebers"], kurz: "Die Vertragspartei, für die der Arbeitnehmer arbeitet und die ihm den Lohn schuldet.", bedeutung: "Partei des Arbeitsvertrags, in deren Dienst der Arbeitnehmer Arbeit leistet und die ihm dafür den Lohn schuldet. Im Personalverleih ist der Verleiher Arbeitgeber; der Einsatzbetrieb wird es nicht, auch wenn er die Weisungen erteilt.", abgrenzung: [{wort: "Verleiher", id: "verleiher", text: "Verleiher ist der Arbeitgeber in seiner Rolle gegenüber dem Einsatzbetrieb; der Arbeitsvertrag nennt dieselbe Firma Arbeitgeberin."}, {wort: "Einsatzbetrieb", id: "einsatzbetrieb", text: "Der Einsatzbetrieb weist an, zahlt aber keinen Lohn und kann nicht kündigen."}], quellen: [{t: "Art. 319 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_319"}, {t: "Art. 12 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_12"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.2.1"}]},
    {id: "kontaktperson", wort: "Kontaktperson", formen: ["Kontaktperson"], kurz: "Die Person des Einsatzbetriebs, unter der der Arbeitnehmer arbeitet; sie erteilt die Weisungen und unterzeichnet den Wochenrapport.", bedeutung: "Person des Einsatzbetriebs, unter der der Arbeitnehmer mehrheitlich arbeitet, in der Regel der Projektleiter. Sie steht im Einsatzblatt, erteilt die Weisungen und unterzeichnet den Wochenrapport. Das SECO-Muster des Einsatzvertrags sieht dafür ein Feld zuständige Kontaktperson vor.", abgrenzung: [{wort: "Bauleitung", text: "Die Bauleitung leitet die Baustelle für die Bauherrschaft; sie ist nicht Teil des Einsatzbetriebs und erteilt dem Arbeitnehmer keine Weisungen nach dem Verleihvertrag."}, {wort: "unterzeichnende Person", text: "Den Verleihvertrag unterzeichnet für den Einsatzbetrieb, wer ihn vertreten darf; das kann, muss aber nicht die Kontaktperson sein."}], quellen: [{t: "SECO, Muster Einsatzvertrag"}]},
    {id: "inhaber", wort: "Inhaber", formen: ["Inhaber"], kurz: "Wer einen Betrieb allein besitzt; bei einer GmbH der alleinige Stammanteilhalter.", bedeutung: "Bei einer Ein-Personen-GmbH ist Inhaber der alleinige Stammanteilhalter. Betriebe, die ausschliesslich ihren Inhaber oder ihre Mitbesitzer verleihen, brauchen keine Verleihbewilligung; der Inhaber muss dafür keine weiteren Bedingungen erfüllen.", abgrenzung: [{wort: "Mitbesitzer", text: "Mitbesitzer ist, wer an einem Betrieb mit mehreren Beteiligten beteiligt ist; nach der SECO-Weisung 2014/1 gelten für ihn Richtgrössen (Kapitalbeteiligung um 20 Prozent, höchstens fünf Gesellschafter, Eintrag als Geschäftsführer)."}, {wort: "Geschäftsführer", id: "geschaeftsfuehrer", text: "Inhaber sagt etwas über das Eigentum, Geschäftsführer über die Organrolle; im Selbstverleih ist es oft dieselbe Person."}], quellen: [{t: "Art. 28 Abs. 2 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_28"}, {t: "SECO-Weisung 2014/1 zu Art. 28 Abs. 2 AVV"}]},
    {id: "geschaeftsfuehrer", wort: "Geschäftsführer", formen: ["Geschäftsführer", "Geschäftsführers", "Geschäftsführung", "Organ"], kurz: "Die Person, die die Geschäfte einer GmbH führt und sie nach aussen vertritt; ein Organ der Gesellschaft.", bedeutung: "Person, die die Geschäfte der GmbH führt und sie vertritt. Sie handelt als Organ: Was sie in dieser Rolle erklärt, ist eine Erklärung der Gesellschaft. Schliesst die Gesellschaft einen Vertrag mit der Person, die sie dabei vertritt, muss der Vertrag schriftlich abgefasst werden, ausser bei Verträgen des laufenden Geschäfts mit einer Leistung der Gesellschaft bis 1000 Franken.", abgrenzung: [{wort: "Arbeitnehmer", id: "arbeitnehmer", text: "Im Selbstverleih ist dieselbe Person Geschäftsführer (Organ) und Arbeitnehmer; bei der Arbeit handelt sie als Arbeitnehmer nach den Weisungen des Einsatzbetriebs, bei Erklärungen zum Vertrag als Geschäftsführer."}, {wort: "Inhaber", id: "inhaber", text: "Geschäftsführer ist eine Funktion, Inhaber eine Beteiligung."}, {wort: "Gesellschafterversammlung", text: "Oberstes Organ der GmbH; sie setzt unter anderem die Entschädigung der Geschäftsführer fest."}], quellen: [{t: "Art. 809 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_809"}, {t: "Art. 810 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_810"}, {t: "Art. 814 Abs. 4 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_814"}, {t: "Art. 718b OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_718_b"}, {t: "Art. 804 Abs. 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_804"}]},
    {id: "hilfsperson", wort: "Hilfsperson", formen: ["Hilfsperson", "Hilfspersonen"], kurz: "Wer für einen anderen eine Pflicht erfüllt; für ihr Verhalten haftet der andere wie für eigenes.", bedeutung: "Person, die ein Schuldner zur Erfüllung einer Schuldpflicht oder zur Ausübung eines Rechts beizieht. Für den Schaden, den sie in Ausübung ihrer Verrichtungen verursacht, haftet der Schuldner wie für eigenes Verhalten. Im Personalverleih schuldet der Verleiher nach der SECO-Praxis nur die sorgfältige Auswahl des Arbeitnehmers; die Arbeit selbst führt dieser unter den Weisungen des Einsatzbetriebs aus.", abgrenzung: [{wort: "Arbeitnehmer", id: "arbeitnehmer", text: "Arbeitnehmer bezeichnet die Stellung im Arbeitsvertrag, Hilfsperson die Rolle bei der Erfüllung einer bestimmten Pflicht."}, {wort: "Geschäftsherrenhaftung", text: "Art. 55 OR regelt die Haftung des Geschäftsherrn für Schäden, die seine Angestellten Dritten ausserhalb eines Vertrags zufügen."}], quellen: [{t: "Art. 101 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_101"}, {t: "Art. 55 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_55"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.1.4"}]},
    {id: "personalverleih", wort: "Personalverleih", formen: ["Personalverleih", "Personalverleihs", "verleihen", "verleiht"], kurz: "Ein Arbeitgeber überlässt einen seiner Arbeitnehmer einem anderen Betrieb zur Arbeit unter dessen Weisungen.", bedeutung: "Ein Arbeitgeber (Verleiher) überlässt Dritten (Einsatzbetrieben) Arbeitnehmer und tritt ihnen dabei wesentliche Weisungsbefugnisse ab. Das Gesetz kennt drei Formen: Temporärarbeit, Leiharbeit und gelegentliches Überlassen. Ein verliehener Arbeitnehmer darf nicht weiterverliehen werden.", abgrenzung: [{wort: "Arbeitsvermittlung", id: "arbeitsvermittlung", text: "Bei der Vermittlung entsteht ein Arbeitsvertrag direkt mit dem neuen Arbeitgeber; beim Verleih bleibt der Verleiher Arbeitgeber."}, {wort: "Werkvertrag", id: "werkvertrag", text: "Beim Werkvertrag schuldet der Unternehmer ein Ergebnis und arbeitet unter eigener Leitung; beim Verleih schuldet der Verleiher nur die Überlassung des Arbeitnehmers, das Ergebnis verantwortet der Einsatzbetrieb."}, {wort: "Arbeitsgemeinschaft", id: "arbeitsgemeinschaft", text: "Überlassen Betriebe einer Arbeitsgemeinschaft Arbeitnehmer, liegt kein Personalverleih vor, ausser es wird ein wesentliches Weisungsrecht abgetreten."}], quellen: [{t: "Art. 12 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_12"}, {t: "Art. 26 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_26"}, {t: "Art. 27 Abs. 1 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_27"}]},
    {id: "leiharbeit", wort: "Leiharbeit", formen: ["Leiharbeit"], kurz: "Form des Personalverleihs: Der Arbeitnehmer ist hauptsächlich für den Verleih angestellt, und sein Arbeitsvertrag läuft unabhängig von einzelnen Einsätzen.", bedeutung: "Leiharbeit liegt vor, wenn der Zweck des Arbeitsvertrags hauptsächlich im Überlassen des Arbeitnehmers an Einsatzbetriebe liegt und die Dauer des Arbeitsvertrags von einzelnen Einsätzen unabhängig ist. Der Arbeitnehmer hat Anspruch auf Beschäftigung und muss zugewiesene Einsätze übernehmen; fehlen Einsätze, bleibt der Arbeitgeber lohnzahlungspflichtig.", abgrenzung: [{wort: "Temporärarbeit", id: "temporaerarbeit", text: "Bei der Temporärarbeit gilt der Arbeitsvertrag nur für einen einzelnen Einsatz; das Risiko fehlender Einsätze trägt der Arbeitnehmer."}, {wort: "gelegentliches Überlassen", text: "Der Arbeitnehmer arbeitet hauptsächlich für seinen Arbeitgeber und wird nur ausnahmsweise einem Einsatzbetrieb überlassen."}, {wort: "Regiearbeit", id: "regiearbeit", text: "Praxiswort aus dem Bau- und Montagegewerbe für dieselbe Erscheinung; es bezeichnet eine Abrechnungsart, keine Rechtsform."}], quellen: [{t: "Art. 27 Abs. 3 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_27"}, {t: "Art. 28 Abs. 1 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_28"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.2.2"}]},
    {id: "temporaerarbeit", wort: "Temporärarbeit", formen: ["Temporärarbeit"], kurz: "Form des Personalverleihs, bei der der Arbeitsvertrag auf einen einzelnen Einsatz beschränkt ist.", bedeutung: "Temporärarbeit liegt vor, wenn Zweck und Dauer des Arbeitsvertrags zwischen Arbeitgeber und Arbeitnehmer auf einen einzelnen Einsatz bei einem Einsatzbetrieb beschränkt sind. In der Praxis regelt ein Rahmenarbeitsvertrag die allgemeinen Bedingungen, und für jeden Einsatz wird ein Einsatzvertrag abgeschlossen. Der Arbeitnehmer hat keinen Anspruch auf weitere Einsätze und darf angebotene Einsätze ablehnen.", abgrenzung: [{wort: "Leiharbeit", id: "leiharbeit", text: "Bei der Leiharbeit besteht der Arbeitsvertrag unabhängig von den einzelnen Einsätzen weiter."}, {wort: "temporär im Alltag", text: "Umgangssprachlich heisst oft jeder Verleih temporär; rechtlich ist Temporärarbeit nur die Form nach Art. 27 Abs. 2 AVV."}], quellen: [{t: "Art. 27 Abs. 2 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_27"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.2.2"}]},
    {id: "arbeitsvermittlung", wort: "Arbeitsvermittlung", formen: ["Arbeitsvermittlung", "Vermittler"], kurz: "Stellensuchende und Arbeitgeber werden zusammengeführt, damit sie einen Arbeitsvertrag miteinander abschliessen.", bedeutung: "Wer regelmässig und gegen Entgelt Arbeit vermittelt, indem er Stellensuchende und Arbeitgeber zum Abschluss von Arbeitsverträgen zusammenführt (Vermittler), braucht eine Betriebsbewilligung des kantonalen Arbeitsamts. Der Arbeitsvertrag entsteht direkt zwischen dem Stellensuchenden und dem Arbeitgeber.", abgrenzung: [{wort: "Personalverleih", id: "personalverleih", text: "Der Verleiher bleibt selbst Arbeitgeber und überlässt den Arbeitnehmer nur zur Arbeit; der Vermittler wird nie Arbeitgeber."}, {wort: "Übertritt", id: "uebertritt", text: "Beim Übertritt stellt der Einsatzbetrieb den bisher verliehenen Arbeitnehmer selbst an; das ist keine Vermittlung durch den Verleiher."}], quellen: [{t: "Art. 2 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_2"}]},
    {id: "bewilligung", wort: "Verleihbewilligung", formen: ["Verleihbewilligung", "Bewilligung"], kurz: "Betriebsbewilligung des kantonalen Arbeitsamts, die braucht, wer gewerbsmässig Personal verleiht.", bedeutung: "Arbeitgeber, die Einsatzbetrieben gewerbsmässig Arbeitnehmer überlassen, benötigen eine Betriebsbewilligung des kantonalen Arbeitsamts; für den Verleih ins Ausland zusätzlich eine des SECO. Bewilligungspflichtig sind nur Temporärarbeit und Leiharbeit. Betriebe, die ausschliesslich den Inhaber oder die Mitbesitzer des Betriebs verleihen, sind nicht bewilligungspflichtig.", abgrenzung: [{wort: "Installationsbewilligung", id: "installationsbewilligung", text: "Die Installationsbewilligung erteilt das Eidgenössische Starkstrominspektorat für elektrische Installationen; sie hat mit dem Verleih nichts zu tun."}, {wort: "Arbeitszeitbewilligung", text: "Nacht- und Sonntagsarbeit braucht nach Arbeitsgesetz eine behördliche Bewilligung; diese holt im Verleih der Einsatzbetrieb ein."}], quellen: [{t: "Art. 12 Abs. 1 und 2 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_12"}, {t: "Art. 28 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_28"}, {t: "SECO-Weisung 2014/1 zu Art. 28 Abs. 2 AVV"}]},
    {id: "arbeitsgemeinschaft", wort: "Arbeitsgemeinschaft", formen: ["Arbeitsgemeinschaft", "ARGE"], kurz: "Zusammenschluss mehrerer Unternehmen für ein gemeinsames Bauvorhaben.", bedeutung: "Zusammenschluss mehrerer Betriebe für ein Bauvorhaben. Überlassen die beteiligten Betriebe der Arbeitsgemeinschaft Arbeitnehmer, liegt kein Personalverleih vor, es sei denn, es wird ein wesentliches Weisungsrecht abgetreten.", abgrenzung: [{wort: "Weiterverleih", text: "Ein verliehener Arbeitnehmer darf nicht weiterverliehen werden (Unter- oder Zwischenverleih); die Arbeit in einer Arbeitsgemeinschaft ist kein Weiterverleih, solange das Weisungsrecht nicht übergeht."}, {wort: "andere Unternehmen auf der Baustelle", text: "Arbeiten mehrere Firmen nebeneinander auf derselben Baustelle, bilden sie damit noch keine Arbeitsgemeinschaft."}], quellen: [{t: "Art. 26 Abs. 3 und 4 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_26"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.2.5"}]},
    {id: "verleihvertrag", wort: "Verleihvertrag", formen: ["Verleihvertrag", "Verleihvertrags", "Verleihverträge"], kurz: "Der schriftliche Vertrag zwischen Verleiher und Einsatzbetrieb über den Einsatz eines Arbeitnehmers.", bedeutung: "Vertrag zwischen Verleiher und Einsatzbetrieb; er muss schriftlich abgeschlossen werden. Das Gesetz verlangt darin namentlich die beruflichen Qualifikationen und die Art der Arbeit, den Arbeitsort und den Beginn des Einsatzes, die Dauer des Einsatzes oder die Kündigungsfristen, die Arbeitszeiten und die Kosten des Verleihs. Im Vertragswerk besteht er aus dem Einsatzblatt und den Vertragsbedingungen.", abgrenzung: [{wort: "Arbeitsvertrag", id: "arbeitsvertrag", text: "Den Arbeitsvertrag schliesst der Verleiher mit dem Arbeitnehmer; der Einsatzbetrieb ist daran nicht beteiligt."}, {wort: "Einsatzvertrag", id: "einsatzvertrag", text: "Einsatzvertrag heisst bei der Temporärarbeit der Arbeitsvertrag für einen einzelnen Einsatz, nicht der Vertrag mit dem Einsatzbetrieb."}], quellen: [{t: "Art. 22 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "SECO, Muster Verleihvertrag"}]},
    {id: "einsatzblatt", wort: "Einsatzblatt", formen: ["Einsatzblatt", "Einsatzblatts"], kurz: "Erste Seite des Verleihvertrags mit den Angaben zum einzelnen Einsatz.", bedeutung: "Teil des Verleihvertrags mit den einsatzbezogenen Angaben (Arbeitnehmer, Qualifikation, Art der Arbeit, Arbeitsort, Beginn und Dauer, Stunden je Wochentag, Ansatz, Kontaktperson). Die SECO-Weisungen erlauben, Einsatzbezogenes im eigentlichen Verleihvertrag und dauernd Geltendes in allgemeinen Bedingungen zu regeln. Das Wort selbst ist kein Gesetzeswort.", abgrenzung: [{wort: "Vertragsbedingungen", id: "vertragsbedingungen", text: "Die Vertragsbedingungen gelten für jeden Einsatz gleich; das Einsatzblatt enthält, was sich je Einsatz ändert."}, {wort: "Vertragsblatt", text: "Gegenstück im Arbeitsvertrag: die erste Seite mit Parteien, Lohn und Abzügen."}], quellen: [{t: "Art. 22 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.11.11"}]},
    {id: "vertragsbedingungen", wort: "Vertragsbedingungen", formen: ["Vertragsbedingungen"], kurz: "Die dauernd geltenden Regeln eines Vertrags, in Ziffern gegliedert.", bedeutung: "Die dauernd geltenden Regeln des Verleihvertrags oder des Arbeitsvertrags. Zusammen mit dem Einsatzblatt bzw. dem Vertragsblatt bilden sie den Vertrag.", abgrenzung: [{wort: "Allgemeine Geschäftsbedingungen", id: "agb", text: "AGB sind vorformulierte Bedingungen einer Partei für viele Verträge; die Vertragsbedingungen sind Teil dieses einen Vertrags und von beiden Parteien unterzeichnet."}, {wort: "Einsatzblatt", id: "einsatzblatt", text: "Das Einsatzblatt enthält die Angaben je Einsatz."}], quellen: [{t: "SECO-Weisungen zum AVG, Ziff. 3.11.11"}]},
    {id: "agb", wort: "Allgemeine Geschäftsbedingungen", formen: ["Allgemeine Geschäftsbedingungen", "AGB"], kurz: "Vorformulierte Bedingungen, die eine Partei für viele Verträge verwendet; sie gelten nur, wenn sie Vertragsinhalt werden.", bedeutung: "Vertragsbedingungen, die eine Partei im Voraus für eine Vielzahl von Verträgen formuliert. Sie gelten nur, soweit die andere Partei sie übernimmt. Der Verleihvertrag lässt AGB des Einsatzbetriebs nur gelten, wenn das Einsatzblatt oder ein Zusatz sie mit Titel und Fassung ausdrücklich übernimmt.", abgrenzung: [{wort: "Vertragsbedingungen", id: "vertragsbedingungen", text: "Die Vertragsbedingungen des Vertragswerks sind Teil des einzelnen, unterzeichneten Vertrags."}, {wort: "Bestellung, Auftragsbestätigung", text: "Ein blosser Verweis auf AGB in einer Bestellung oder Auftragsbestätigung macht sie nach dem Verleihvertrag nicht zum Vertragsinhalt."}], quellen: [{t: "SECO-Weisungen zum AVG, Ziff. 3.11.11"}]},
    {id: "zusatz", wort: "Zusatz zum Verleihvertrag", formen: ["Zusatz zum Verleihvertrag", "Zusatz", "Zusätze"], kurz: "Schriftliche Änderung oder Ergänzung des Verleihvertrags, die beide Parteien unterzeichnen.", bedeutung: "Änderung oder Ergänzung des Einsatzblatts oder der Vertragsbedingungen, die beide Parteien unterzeichnen. Die SECO-Weisungen nennen sie schriftlichen Vertragszusatz. Erklärungen per E-Mail ändern den Verleihvertrag nicht.", abgrenzung: [{wort: "Nachtrag", id: "nachtrag", text: "Nachtrag heisst im Arbeitsvertrag dessen Änderung; Zusatz bleibt dem Verleihvertrag."}, {wort: "Zusatz zum Leiharbeitsvertrag", text: "So nennt das SECO die Mitteilung der Angaben je Einsatz an den Arbeitnehmer; das ist eine andere Sache."}], quellen: [{t: "Art. 12 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_12"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.8.13"}]},
    {id: "nachtrag", wort: "Nachtrag", formen: ["Nachtrag", "Nachträge"], kurz: "Schriftliche, fortlaufend nummerierte Änderung des Arbeitsvertrags.", bedeutung: "Von beiden Parteien unterzeichnete Änderung oder Ergänzung des Arbeitsvertrags. Hat das Gesetz für einen Vertrag die Schriftform vorgeschrieben, gilt sie auch für seine Abänderung.", abgrenzung: [{wort: "Zusatz zum Verleihvertrag", id: "zusatz", text: "Die Änderung des Verleihvertrags heisst im Vertragswerk Zusatz."}, {wort: "Nachtrag im Bauwesen", text: "Auf dem Bau meint Nachtrag oft eine Mehrforderung zum Werkpreis; im Arbeitsvertrag ist nur die Vertragsänderung gemeint."}], quellen: [{t: "Art. 12 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_12"}, {t: "Art. 16 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_16"}]},
    {id: "arbeitsvertrag", wort: "Arbeitsvertrag", formen: ["Arbeitsvertrag", "Arbeitsvertrags", "Arbeitsverhältnis", "Arbeitsverhältnisses"], kurz: "Vertrag, mit dem sich der Arbeitnehmer verpflichtet, im Dienst des Arbeitgebers gegen Lohn zu arbeiten.", bedeutung: "Durch den Einzelarbeitsvertrag verpflichtet sich der Arbeitnehmer auf bestimmte oder unbestimmte Zeit zur Leistung von Arbeit im Dienst des Arbeitgebers und dieser zur Entrichtung eines Lohnes. Das daraus entstehende Rechtsverhältnis heisst Arbeitsverhältnis; es beginnt, dauert und endet. Im Personalverleih schliesst der Verleiher den Arbeitsvertrag in der Regel schriftlich und mit den Pflichtpunkten des AVG ab.", abgrenzung: [{wort: "Verleihvertrag", id: "verleihvertrag", text: "Der Verleihvertrag regelt das Verhältnis zwischen Verleiher und Einsatzbetrieb, nicht zum Arbeitnehmer."}, {wort: "Gesamtarbeitsvertrag", id: "gav", text: "Der GAV wird zwischen Verbänden abgeschlossen und setzt Mindestbedingungen für viele Arbeitsverträge."}, {wort: "Werkvertrag und Auftrag", id: "werkvertrag", text: "Wer selbständig ein Werk oder einen Auftrag übernimmt, ist nicht Arbeitnehmer und arbeitet unter eigener Leitung."}], quellen: [{t: "Art. 319 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_319"}, {t: "Art. 19 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_19"}, {t: "Art. 27 Abs. 3 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_27"}]},
    {id: "einsatzvertrag", wort: "Einsatzvertrag", formen: ["Einsatzvertrag", "Einsatzverträge"], kurz: "Bei der Temporärarbeit der Arbeitsvertrag zwischen Verleiher und Arbeitnehmer für einen einzelnen Einsatz.", bedeutung: "Arbeitsvertrag zwischen Verleiher und Arbeitnehmer für einen einzelnen Einsatz in einem Einsatzbetrieb. Er setzt den Rahmenarbeitsvertrag in Kraft; erst durch ihn entsteht das Arbeitsverhältnis. Jeder neue Einsatz braucht einen neuen Einsatzvertrag.", abgrenzung: [{wort: "Verleihvertrag", id: "verleihvertrag", text: "Der Vertrag mit dem Einsatzbetrieb heisst Verleihvertrag, nie Einsatzvertrag."}, {wort: "Rahmenarbeitsvertrag", id: "rahmenarbeitsvertrag", text: "Der Rahmenarbeitsvertrag regelt die allgemeinen Bedingungen für alle Einsätze, begründet aber allein kein Arbeitsverhältnis."}, {wort: "Leiharbeit", id: "leiharbeit", text: "Bei der Leiharbeit gibt es keinen Einsatzvertrag; der Arbeitsvertrag gilt unabhängig von den Einsätzen."}], quellen: [{t: "SECO-Weisungen zum AVG, Ziff. 3.1.2.2"}, {t: "SECO, Muster Einsatzvertrag"}]},
    {id: "werkvertrag", wort: "Werkvertrag", formen: ["Werkvertrag", "Werk", "Ergebnis der Arbeit", "Nachbesserung", "Minderung"], kurz: "Vertrag, mit dem der Unternehmer ein Werk, also ein Ergebnis, schuldet. Der Verleiher schuldet kein Werk.", bedeutung: "Durch den Werkvertrag verpflichtet sich der Unternehmer zur Herstellung eines Werkes und der Besteller zur Leistung einer Vergütung. Der Unternehmer arbeitet unter eigener Leitung und haftet für Mängel des Werks; der Besteller kann Nachbesserung oder Minderung des Preises verlangen. Der Verleiher schuldet weder ein Werk noch das Ergebnis der Arbeit; er haftet nach der SECO-Praxis nur für die gute Auswahl des Arbeitnehmers.", abgrenzung: [{wort: "Personalverleih", id: "personalverleih", text: "Beim Verleih liegt das Weisungsrecht beim Einsatzbetrieb, abgerechnet wird nach Stunden, und die Gefahr der Schlechterfüllung trägt der Einsatzbetrieb."}, {wort: "Auftrag", id: "auftrag", text: "Beim Auftrag wird ein sorgfältiges Tätigwerden geschuldet, kein bestimmtes Ergebnis."}, {wort: "Subunternehmer", id: "subunternehmer", text: "Wer einen Teil eines Werkvertrags selbständig übernimmt, ist Subunternehmer, nicht Verleiher."}], quellen: [{t: "Art. 363 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_363"}, {t: "Art. 368 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_368"}, {t: "Art. 26 Abs. 2 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_26"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.1.4"}]},
    {id: "auftrag", wort: "Auftrag", formen: ["Auftrag", "Auftrags"], kurz: "Vertrag, mit dem jemand ein Geschäft oder eine Dienstleistung sorgfältig zu besorgen übernimmt, ohne einen Erfolg zu schulden.", bedeutung: "Durch die Annahme eines Auftrags verpflichtet sich der Beauftragte, die ihm übertragenen Geschäfte oder Dienste vertragsgemäss zu besorgen. Er schuldet sorgfältiges Tätigwerden, aber keinen bestimmten Erfolg, und erbringt die Leistung selbständig.", abgrenzung: [{wort: "Werkvertrag", id: "werkvertrag", text: "Der Werkvertrag verlangt ein bestimmtes Ergebnis; der Auftrag nur die sorgfältige Besorgung."}, {wort: "Personalverleih", id: "personalverleih", text: "Beim Verleih überlässt der Verleiher einen Arbeitnehmer zur Arbeit nach fremden Weisungen; er besorgt keinen Auftrag."}, {wort: "Auftragsbestätigung", text: "Im Geschäftsalltag heisst auch eine Bestellung Auftrag; das ist kein Auftrag im Sinn des OR."}], quellen: [{t: "Art. 394 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_394"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.1.4"}]},
    {id: "schriftlich", wort: "schriftlich", formen: ["schriftlich", "Schriftform"], kurz: "Mit Unterschrift auf Papier oder mit qualifizierter elektronischer Signatur; eine gewöhnliche E-Mail genügt nicht.", bedeutung: "Ein Vertrag, für den die Schriftform gilt, muss die Unterschriften aller Personen tragen, die sich verpflichten. Die eigenhändige Unterschrift ist gleichgestellt mit der qualifizierten elektronischen Signatur. Haben die Parteien die Schriftform vereinbart, gilt im Zweifel ebenso, dass sie erst mit dieser Form gebunden sein wollen.", abgrenzung: [{wort: "per E-Mail", text: "Das Vertragswerk sagt ausdrücklich per E-Mail, wo eine E-Mail genügt; eine gewöhnliche E-Mail trägt keine Unterschrift im Sinn des OR."}, {wort: "formlos", text: "Formlos bedeutet: auch mündlich gültig."}], quellen: [{t: "Art. 13 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_13"}, {t: "Art. 14 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_14"}, {t: "Art. 16 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_16"}]},
    {id: "unterzeichnen", wort: "unterzeichnen", formen: ["unterzeichnen", "unterzeichnet", "Unterschrift"], kurz: "Eigenhändig unterschreiben; gleichgestellt ist die qualifizierte elektronische Signatur.", bedeutung: "Eine Urkunde mit dem eigenen Namen eigenhändig unterschreiben. Die qualifizierte elektronische Signatur ist der eigenhändigen Unterschrift gleichgestellt; andere digitale Unterschriften lässt das SECO für Verträge im Personalverleih nicht zu.", abgrenzung: [{wort: "Visum", id: "visum", text: "Ein Visum (Kürzel, Haken) bestätigt in der Praxis eine Prüfung, ist aber keine Unterschrift im Sinn des OR."}, {wort: "Zustimmung", id: "zustimmung", text: "Eine Zustimmung kann je nach Vertrag auch ohne Unterschrift gültig sein, etwa per E-Mail."}], quellen: [{t: "Art. 14 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_14"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.8.2 und 3.11.1"}]},
    {id: "zustimmung", wort: "Zustimmung", formen: ["Zustimmung", "zugestimmt", "stimmt zu"], kurz: "Erklärung, mit der jemand eine Handlung eines anderen billigt; die Form legt der Vertrag fest.", bedeutung: "Erklärung, mit der eine Partei oder der Arbeitnehmer eine Handlung billigt. Das OR braucht Zustimmung als Oberbegriff; welche Form genügt, bestimmt die jeweilige Vertragsziffer oder das Gesetz. Im Datenschutz verlangt die Arbeitsvermittlungsverordnung, dass der Verleiher Daten des Arbeitnehmers grundsätzlich nur mit dessen Zustimmung bearbeitet; die Zustimmung ist schriftlich zu geben und jederzeit widerruflich.", abgrenzung: [{wort: "Genehmigung", text: "Genehmigung meint im OR die nachträgliche Billigung eines schon geschlossenen Geschäfts."}, {wort: "Vereinbarung", text: "Was beide Parteien gemeinsam abmachen, ist eine Vereinbarung, keine Zustimmung."}, {wort: "Einwilligung", id: "einwilligung", text: "Das Datenschutzgesetz sagt Einwilligung für dieselbe Sache."}], quellen: [{t: "Art. 16 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_16"}, {t: "Art. 47 Abs. 1 und 4 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_47"}]},
    {id: "zugang", wort: "Zugang", formen: ["Zugang", "zugeht", "geht zu"], kurz: "Eine Erklärung geht zu, sobald sie in den Machtbereich des Empfängers gelangt und er sie zur Kenntnis nehmen kann.", bedeutung: "Eine Erklärung geht zu, sobald sie in den Machtbereich des Empfängers gelangt und dieser unter gewöhnlichen Umständen von ihr Kenntnis nehmen kann; ob er sie tatsächlich liest, ist nicht entscheidend. Fristen, die mit einer Erklärung beginnen, laufen ab dem Zugang. Der Verleihvertrag legt fest, wann eine E-Mail zugeht.", abgrenzung: [{wort: "Versand", text: "Massgebend ist nicht der Zeitpunkt des Absendens, sondern der Zugang."}, {wort: "Zustellung", text: "Zustellung ist ein Wort des Verfahrensrechts für behördliche und gerichtliche Sendungen."}], quellen: [{t: "BGE 137 III 208 E. 3.1.2"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.8.12"}]},
    {id: "zwingendes-recht", wort: "zwingendes Recht", formen: ["zwingendes Recht", "zwingenden Recht"], kurz: "Gesetzesbestimmungen, von denen ein Vertrag nicht abweichen darf.", bedeutung: "Bestimmungen, die durch Vereinbarung nicht oder nur zugunsten einer geschützten Partei geändert werden können. Das Arbeitsrecht des OR zählt sie auf: von einem Teil darf gar nicht, von einem anderen nicht zuungunsten des Arbeitnehmers abgewichen werden. Ein Vertragsinhalt, der gegen zwingendes Recht verstösst, ist nichtig.", abgrenzung: [{wort: "dispositives Recht", text: "Gesetzesbestimmungen, die nur gelten, wenn der Vertrag nichts anderes bestimmt."}, {wort: "nichtig", id: "nichtig", text: "Nichtigkeit ist die Folge eines Verstosses gegen zwingendes Recht."}], quellen: [{t: "Art. 19 Abs. 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_19"}, {t: "Art. 361 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_361"}, {t: "Art. 362 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_362"}]},
    {id: "gav", wort: "Gesamtarbeitsvertrag", formen: ["Gesamtarbeitsvertrag", "Gesamtarbeitsvertrags", "GAV"], kurz: "Vertrag zwischen Arbeitgeber- und Arbeitnehmerverbänden über Mindestbedingungen der Arbeitsverhältnisse einer Branche.", bedeutung: "Durch den Gesamtarbeitsvertrag stellen Arbeitgeber oder deren Verbände und Arbeitnehmerverbände gemeinsam Bestimmungen über Abschluss, Inhalt und Beendigung der einzelnen Arbeitsverhältnisse auf. Für die Elektroinstallation gilt der GAV der Schweizerischen Elektrobranche. Untersteht ein Einsatzbetrieb einem allgemeinverbindlich erklärten GAV, muss der Verleiher dessen Lohn- und Arbeitszeitbestimmungen einhalten.", abgrenzung: [{wort: "Arbeitsvertrag", id: "arbeitsvertrag", text: "Der Arbeitsvertrag wird zwischen Arbeitgeber und Arbeitnehmer geschlossen; er darf von den Mindestbedingungen des GAV nur zugunsten des Arbeitnehmers abweichen."}, {wort: "Allgemeinverbindlicherklärung", id: "allgemeinverbindlicherklaerung", text: "Erst sie macht einen GAV auch für Betriebe verbindlich, die keinem vertragschliessenden Verband angehören."}], quellen: [{t: "Art. 356 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_356"}, {t: "Art. 20 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_20"}, {t: "Art. 48a AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_a"}]},
    {id: "allgemeinverbindlicherklaerung", wort: "Allgemeinverbindlicherklärung", formen: ["Allgemeinverbindlicherklärung", "allgemeinverbindlich erklärten", "allgemeinverbindlich erklärte"], kurz: "Behördlicher Entscheid, der einen GAV für alle Betriebe und Arbeitnehmer seines Geltungsbereichs verbindlich macht.", bedeutung: "Mit der Allgemeinverbindlicherklärung dehnt der Bundesrat oder der Kanton den Geltungsbereich eines Gesamtarbeitsvertrags auf alle Arbeitgeber und Arbeitnehmer der Branche aus, auch auf solche ohne Verbandsmitgliedschaft. Für den Personalverleih folgt daraus: Untersteht der Einsatzbetrieb einem allgemeinverbindlich erklärten GAV, gelten dessen Lohn- und Arbeitszeitbestimmungen auch gegenüber dem verliehenen Arbeitnehmer.", abgrenzung: [{wort: "Gesamtarbeitsvertrag", id: "gav", text: "Ohne Allgemeinverbindlicherklärung bindet ein GAV nur die Mitglieder der vertragschliessenden Verbände."}], quellen: [{t: "Art. 1 Abs. 1 AVEG", url: "https://www.fedlex.admin.ch/eli/cc/1956/1543_1645_1658/de#art_1"}, {t: "Art. 7 AVEG", url: "https://www.fedlex.admin.ch/eli/cc/1956/1543_1645_1658/de#art_7"}, {t: "Art. 20 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_20"}, {t: "Art. 48a AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_a"}]},
    {id: "paritaetische-organe", wort: "paritätische Organe", formen: ["paritätische Organe", "paritätischen Organe", "paritätischen Organen", "Paritätische Kommission", "Paritätische Landeskommission"], kurz: "Von Arbeitgeber- und Arbeitnehmerseite gemeinsam besetzte Stellen, die die Einhaltung eines GAV kontrollieren.", bedeutung: "Organe, in denen Arbeitgeber- und Arbeitnehmerverbände gleich vertreten sind und die den Vollzug eines GAV überwachen. Das im allgemeinverbindlich erklärten GAV vorgesehene paritätische Organ ist auch zur Kontrolle des Verleihers berechtigt und kann bei Verstössen eine Konventionalstrafe und die Kontrollkosten auferlegen. In der Elektrobranche sind es die Paritätische Landeskommission und die regionalen Paritätischen Kommissionen.", abgrenzung: [{wort: "Weisungsrecht", id: "weisungsrecht", text: "Die Kontrollen der paritätischen Organe prüfen die Arbeitsbedingungen; mit dem Weisungsrecht über die Arbeit haben sie nichts zu tun."}, {wort: "Kontrolle elektrischer Installationen", id: "schlusskontrolle", text: "Kontrollen nach NIV betreffen die Sicherheit der Installation, nicht die Arbeitsbedingungen."}], quellen: [{t: "Art. 20 Abs. 2 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_20"}, {t: "GAV Elektrobranche, Art. 8 und 9"}]},
    {id: "weiterbildungs-und-vollzugskosten", wort: "Weiterbildungs- und Vollzugskosten", formen: ["Weiterbildungs- und Vollzugskosten", "Weiterbildungs- und Vollzugskostenbeitrag"], kurz: "Beitrag, den ein allgemeinverbindlich erklärter GAV für Weiterbildung und Kontrollen erhebt; Verleiher zahlen ihn anteilsmässig.", bedeutung: "Sieht ein allgemeinverbindlich erklärter GAV einen obligatorischen Beitrag an Weiterbildungs- und Vollzugskosten vor, gilt er auch für den Verleiher, anteilsmässig nach der Dauer des Einsatzes. Arbeitnehmer und Arbeitgeber leisten je einen Beitrag; der Arbeitgeber zieht den Anteil des Arbeitnehmers vom Lohn ab und überweist die Beiträge der Paritätischen Kommission.", abgrenzung: [{wort: "Sozialversicherungsbeiträge", text: "AHV, ALV und Unfallversicherung beruhen auf Gesetz; der Vollzugskostenbeitrag beruht auf dem GAV."}], quellen: [{t: "Art. 20 Abs. 1 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_20"}, {t: "Art. 48b AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_b"}, {t: "GAV Elektrobranche, Art. 11"}]},
    {id: "installationsbewilligung", wort: "Installationsbewilligung", formen: ["Installationsbewilligung", "technische Aufsicht"], kurz: "Bewilligung des Starkstrominspektorats, elektrische Installationen zu erstellen; der Inhaber übt die technische Aufsicht aus.", bedeutung: "Wer elektrische Installationen erstellt, ändert oder instand stellt, braucht eine Installationsbewilligung des Inspektorats. Ein Betrieb erhält die allgemeine Bewilligung, wenn er eine fachkundige Person beschäftigt, die die technische Aufsicht wirksam ausübt (fachkundiger Leiter). Er darf Einzelpersonen beiziehen, wenn er sie wie eigene Leute in seine Betriebsorganisation integriert; Verantwortung und Schlusskontrolle bleiben bei ihm.", abgrenzung: [{wort: "Verleihbewilligung", id: "bewilligung", text: "Die Verleihbewilligung betrifft das Überlassen von Arbeitnehmern, nicht die Installationsarbeit."}, {wort: "Weisungsrecht", id: "weisungsrecht", text: "Die technische Aufsicht nach NIV ist eine elektrotechnische Pflicht des Bewilligungsinhabers; das Weisungsrecht ist die arbeitsrechtliche Befugnis aus dem Verleih."}], quellen: [{t: "Art. 6 NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_6"}, {t: "Art. 9 Abs. 1 NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_9"}, {t: "Art. 10b NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_10_b"}]},
    {id: "schlusskontrolle", wort: "Schlusskontrolle und Sicherheitsnachweis", formen: ["Schlusskontrolle", "Sicherheitsnachweis"], kurz: "Prüfung einer elektrischen Installation vor der Übergabe an den Eigentümer; ihr Ergebnis hält der Sicherheitsnachweis fest.", bedeutung: "Vor der Übergabe einer Installation an den Eigentümer führt der Bewilligungsinhaber durch eine fachkundige oder kontrollberechtigte Person die Schlusskontrolle durch. Ihre Ergebnisse stehen im Sicherheitsnachweis, den der Bewilligungsinhaber dem Eigentümer übergibt. Bei beigezogenen Einzelpersonen bleibt die Schlusskontrolle in jedem Fall beim beiziehenden Betrieb.", abgrenzung: [{wort: "Erstprüfung", text: "Die baubegleitende Erstprüfung findet vor der Inbetriebnahme statt und wird protokolliert; sie ersetzt die Schlusskontrolle nicht."}, {wort: "Abnahmekontrolle, periodische Kontrolle", text: "Diese Kontrollen machen unabhängige Kontrollorgane, nicht der Ersteller der Installation."}], quellen: [{t: "Art. 24 NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_24"}, {t: "Art. 37 NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_37"}, {t: "Art. 10b Abs. 2 NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_10_b"}]},
    {id: "fachkundige-person", wort: "fachkundige Person", formen: ["fachkundige Person", "fachkundigen"], kurz: "Wer nach NIV die höhere Fachprüfung als Elektroinstallations- und Sicherheitsexperte oder eine gleichwertige Ausbildung hat.", bedeutung: "Fachkundig ist eine Person, welche die höhere Fachprüfung (Meisterprüfung) als Elektroinstallations- und Sicherheitsexperte bestanden hat oder die Voraussetzungen der Verordnung für gleichwertige Abschlüsse mit Praxis erfüllt. Ein Elektroinstallateur EFZ ist allein nicht fachkundig. Kontrollberechtigt ist, wer fachkundig ist oder die sicherheitsrelevanten Teile der Berufsprüfung als Elektroprojektleiter bestanden hat.", abgrenzung: [{wort: "Qualifikation", id: "qualifikation", text: "Der Elektroinstallateur EFZ darf Installationsarbeiten ausführen und erstmalig in Betrieb nehmen, aber keine Schlusskontrolle machen."}, {wort: "sachverständige Person", text: "Begriff der Starkstromverordnung für Starkstromanlagen, nicht der NIV."}], quellen: [{t: "Art. 8 NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_8"}, {t: "Art. 10a NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_10_a"}, {t: "Art. 27 Abs. 1 NIV", url: "https://www.fedlex.admin.ch/eli/cc/2002/22/de#art_27"}]},
    {id: "qualifikation", wort: "Qualifikation", formen: ["Qualifikation", "Anforderungsprofil", "Ausbildungsnachweis", "Ausbildungsnachweise", "Ausbildungsnachweisen"], kurz: "Die berufliche Ausbildung des Arbeitnehmers, für die der Verleiher einsteht; was darüber hinaus verlangt ist, steht im Anforderungsprofil.", bedeutung: "Die beruflichen Qualifikationen des Arbeitnehmers muss der Verleihvertrag angeben. Verlangt die Art der Arbeit Kenntnisse oder Nachweise über die Qualifikation hinaus (Anforderungsprofil), nennt der Einsatzbetrieb sie vor Vertragsschluss. Ausbildungsnachweise sind Belege einzelner Ausbildungen, etwa Kurse zur Arbeitssicherheit.", abgrenzung: [{wort: "Art der Arbeit", id: "art-der-arbeit", text: "Die Qualifikation beschreibt, was der Arbeitnehmer kann; die Art der Arbeit, was er beim Einsatzbetrieb tut."}, {wort: "fachkundige Person", id: "fachkundige-person", text: "Fachkundig im Sinn der NIV ist mehr als die Berufslehre."}], quellen: [{t: "Art. 22 Abs. 1 Bst. b AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "SECO, Muster Verleihvertrag, Ziff. 7"}]},
    {id: "art-der-arbeit", wort: "Art der Arbeit", formen: ["Art der Arbeit"], kurz: "Was der Arbeitnehmer beim Einsatzbetrieb tut; sie begrenzt das Weisungsrecht.", bedeutung: "Beschreibung der Arbeit, die der Arbeitnehmer im Einsatz leistet. Sie muss im Verleihvertrag und im Arbeitsvertrag stehen. Weisungen und Ersatzarbeit sind nur im Rahmen der Art der Arbeit zulässig.", abgrenzung: [{wort: "Qualifikation", id: "qualifikation", text: "Die Qualifikation ist die Ausbildung des Arbeitnehmers, nicht seine Aufgabe im Einsatz."}], quellen: [{t: "Art. 22 Abs. 1 Bst. b AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "Art. 19 Abs. 2 Bst. a AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_19"}]},
    {id: "weisungsrecht", wort: "Weisungsrecht", formen: ["Weisungsrecht", "Weisung", "Weisungen", "einbindet", "eingebunden", "Einbindung"], kurz: "Recht, dem Arbeitnehmer Anordnungen über die Ausführung der Arbeit zu geben; im Verleih liegt es beim Einsatzbetrieb.", bedeutung: "Recht, über die Ausführung der Arbeit und das Verhalten im Betrieb allgemeine Anordnungen und besondere Weisungen zu erteilen; der Arbeitnehmer hat sie nach Treu und Glauben zu befolgen. Beim Verleih tritt der Verleiher dem Einsatzbetrieb wesentliche Weisungsbefugnisse ab. Ein Merkmal ist auch, dass der Arbeitnehmer in persönlicher, organisatorischer, sachlicher und zeitlicher Hinsicht in die Arbeitsorganisation des Einsatzbetriebs eingebunden wird. Mit dem Weisungsrecht geht keine Befugnis zur Kündigung über.", abgrenzung: [{wort: "Kontrollrecht", id: "kontrollrecht", text: "Manche Verträge sagen Weisungs- und Kontrollrecht; das Vertragswerk spricht nur vom Weisungsrecht, um Verwechslungen mit Kontrollen der paritätischen Organe und elektrischen Kontrollen zu vermeiden."}, {wort: "technische Aufsicht", id: "installationsbewilligung", text: "Die technische Aufsicht nach NIV ist eine elektrotechnische Pflicht des Bewilligungsinhabers."}, {wort: "Hausherr", text: "Auch ohne Verleih darf ein Betrieb fremden Arbeitern Anordnungen als Hausherr geben (Türen, Sicherheit); das ist kein wesentliches Weisungsrecht."}], quellen: [{t: "Art. 321d OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_321_d"}, {t: "Art. 26 Abs. 1 und 2 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_26"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.1.4 und 3.11.4"}]},
    {id: "einsatz", wort: "Einsatz", formen: ["Einsatz", "Einsatzes", "Einsätze", "Einsätzen"], kurz: "Der ganze Verleih des Arbeitnehmers an einen Einsatzbetrieb, von Beginn bis Ende.", bedeutung: "Die Arbeit des Arbeitnehmers bei einem Einsatzbetrieb nach einem Verleihvertrag, von ihrem Beginn bis zu ihrem Ende. Verleihvertrag und Arbeitsvertrag müssen Beginn und Dauer des Einsatzes oder die Kündigungsfristen angeben.", abgrenzung: [{wort: "Arbeitstag", id: "arbeitstag", text: "Ein einzelner Tag ist kein Einsatz, sondern ein Arbeitstag."}, {wort: "Kalenderwoche", text: "Die Woche, über die ein Wochenrapport abrechnet, ist ebenfalls kein Einsatz."}, {wort: "Einsatzvertrag", id: "einsatzvertrag", text: "Einsatzvertrag heisst der Arbeitsvertrag der Temporärarbeit für einen Einsatz."}], quellen: [{t: "Art. 22 Abs. 1 Bst. c und d AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "Art. 19 Abs. 2 Bst. b und c AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_19"}]},
    {id: "arbeitsort", wort: "Arbeitsort", formen: ["Arbeitsort", "Arbeitsorts"], kurz: "Der Ort, an dem der Arbeitnehmer arbeitet: Sitz des Einsatzbetriebs und seine Baustellen.", bedeutung: "Ort, an dem die Arbeit geleistet wird; er muss im Verleihvertrag und im Arbeitsvertrag stehen. Im Vertragswerk sind es der Sitz des Einsatzbetriebs und seine Baustellen; ausserhalb des Rayons braucht es die Zustimmung des Verleihers. Bei wechselnden Arbeitsorten gilt für die Frage des anwendbaren GAV nach den SECO-Weisungen der erste im Vertrag genannte.", abgrenzung: [{wort: "Rayon", id: "rayon", text: "Der Rayon bestimmt, wo die Wegzeit im Ansatz enthalten ist; der Arbeitsort, wo gearbeitet wird."}, {wort: "Gerichtsstand", id: "gerichtsstand", text: "Der Ort, an dem der Arbeitnehmer gewöhnlich arbeitet, kann auch einen Gerichtsstand begründen."}], quellen: [{t: "Art. 22 Abs. 1 Bst. c AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "Art. 19 Abs. 2 Bst. b AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_19"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.9.9"}]},
    {id: "rayon", wort: "Rayon", formen: ["Rayon", "Rayons"], kurz: "Gebiet um einen festen Punkt, in dem die Wegzeit nicht gesondert bezahlt wird.", bedeutung: "Nach dem GAV der Elektrobranche kann ein Betrieb ein Gebiet festlegen, das in höchstens 15 Minuten effektiver Wegzeit vom Firmensitz erreichbar ist; innerhalb dieses Rayons gilt die Wegzeit nicht als Arbeitszeit. Im Verleihvertrag bestimmt der Rayon, wo die Wegzeit im Ansatz enthalten ist; massgebend ist die Karte im Einsatzblatt.", abgrenzung: [{wort: "Arbeitsort", id: "arbeitsort", text: "Arbeit ausserhalb des Rayons ist möglich, braucht aber die Zustimmung des Verleihers und kostet die Wegzeit."}, {wort: "Verpflegungsgebiet", text: "Den Ersatz der Mehrkosten für die Verpflegung misst der GAV ebenfalls mit 15 Minuten, aber nach eigener Regel (Art. 33.1 GAV); es ist nicht dasselbe Gebiet."}], quellen: [{t: "GAV Elektrobranche, Art. 27.4"}, {t: "PLK Elektro, Weisung zu Art. 27 GAV, Ziff. 3.2"}]},
    {id: "arbeitszeit", wort: "Arbeitszeit", formen: ["Arbeitszeit", "Arbeitszeiten", "geleistete Arbeitszeit", "geleisteter Arbeitszeit"], kurz: "Die Zeit, in der sich der Arbeitnehmer zur Verfügung halten muss; der Weg von und zur Arbeit gehört nicht dazu.", bedeutung: "Als Arbeitszeit gilt die Zeit, während der sich der Arbeitnehmer zur Verfügung des Arbeitgebers zu halten hat; im Verleih zur Verfügung des Einsatzbetriebs. Der Weg zu und von der Arbeit gilt nicht als Arbeitszeit. In Rechnung gestellt wird die geleistete Arbeitszeit, also die beim Einsatzbetrieb effektiv geleistete und im Wochenrapport erfasste Zeit.", abgrenzung: [{wort: "Pause", id: "pause", text: "Pausen unterbrechen die Arbeitszeit und zählen nicht dazu."}, {wort: "Wegzeit", id: "wegzeit", text: "Wegzeit ausserhalb des Rayons zählt nach dem Vertragswerk als Arbeitszeit, der Arbeitsweg von zu Hause nicht."}, {wort: "Wartezeit", id: "wartezeit", text: "Wartezeit während der Arbeit ist Arbeitszeit."}], quellen: [{t: "Art. 13 Abs. 1 ArGV 1", url: "https://www.fedlex.admin.ch/eli/cc/2000/243/de#art_13"}, {t: "Art. 22 Abs. 1 Bst. e AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.8.14.1"}]},
    {id: "besondere-arbeitszeiten", wort: "besondere Arbeitszeiten", formen: ["besondere Arbeitszeiten", "besonderen Arbeitszeiten", "Nachtarbeit", "Sonntagsarbeit"], kurz: "Arbeit am Samstagnachmittag, in der Nacht, am Sonntag oder an Feiertagen; dafür gilt ein Zuschlag.", bedeutung: "Der GAV der Elektrobranche nennt so die Arbeit zu Zeiten mit Lohnzuschlag: Samstag 13 bis 23 Uhr, Nacht 23 bis 6 Uhr (Nachtarbeit), Sonntage und gesetzlich anerkannte Feiertage von 0 bis 24 Uhr (Sonntags- und Feiertagsarbeit). Sie werden separat von der normalen Arbeitszeit abgerechnet und nur in Geld ausgeglichen. Nach Arbeitsgesetz sind Nacht- und Sonntagsarbeit grundsätzlich verboten, brauchen eine Bewilligung und dürfen nur mit Zustimmung des Arbeitnehmers angeordnet werden; das Gesetz rechnet den Sonntag von Samstag 23 Uhr bis Sonntag 23 Uhr.", abgrenzung: [{wort: "normale Arbeitszeit", text: "Die Zeit ohne Zuschlag; nach GAV Montag bis Freitag 6 bis 23 Uhr und Samstag 6 bis 13 Uhr."}, {wort: "Überzeit", id: "ueberzeit", text: "Überzeit misst die Menge über 50 Stunden in der Woche, nicht die Lage der Arbeit; sie ist keine besondere Arbeitszeit."}], quellen: [{t: "GAV Elektrobranche, Art. 23 bis 25"}, {t: "Art. 16 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_16"}, {t: "Art. 17 Abs. 1 und 6 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_17"}, {t: "Art. 18 Abs. 1 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_18"}, {t: "Art. 19 Abs. 1 und 5 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_19"}]},
    {id: "ueberstunden", wort: "Überstunden", formen: ["Überstunden", "Jahresbruttoarbeitszeit"], kurz: "Arbeit über die vereinbarte Arbeitszeit hinaus; nach GAV Elektro gemessen am Jahr.", bedeutung: "Nach OR ist Überstundenarbeit die Arbeit über die verabredete oder übliche Arbeitszeit hinaus; sie kann im Einverständnis des Arbeitnehmers durch Freizeit von mindestens gleicher Dauer ausgeglichen werden, sonst ist sie mit dem Lohn und einem Zuschlag von mindestens einem Viertel zu entschädigen, soweit nichts anderes schriftlich vereinbart ist. Der GAV der Elektrobranche misst sie jährlich: Überstunden sind die zwischen 6 und 23 Uhr geleisteten Stunden, welche die Jahresbruttoarbeitszeit (Basis 40-Stunden-Woche) übersteigen.", abgrenzung: [{wort: "Überzeit", id: "ueberzeit", text: "Überzeit ist Arbeit über die gesetzliche wöchentliche Höchstarbeitszeit hinaus; Überstunden liegen darunter."}, {wort: "Mehrarbeit", id: "mehrarbeit", text: "Das Vertragswerk braucht weder Mehrarbeit noch Mehrstunden; im Verleihvertrag wird Arbeit über die Stunden je Wochentag umschrieben."}], quellen: [{t: "Art. 321c OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_321_c"}, {t: "GAV Elektrobranche, Art. 20.1 und 21"}]},
    {id: "ueberzeit", wort: "Überzeit", formen: ["Überzeit", "wöchentliche Höchstarbeitszeit", "wöchentlichen Höchstarbeitszeit", "Höchstarbeitszeit"], kurz: "Arbeit über die gesetzliche wöchentliche Höchstarbeitszeit hinaus, für Elektriker über 50 Stunden; Zuschlag 25 Prozent.", bedeutung: "Die wöchentliche Höchstarbeitszeit beträgt 45 Stunden für Arbeitnehmer in industriellen Betrieben sowie für Büropersonal, technische und andere Angestellte, für alle übrigen Arbeitnehmer 50 Stunden; der GAV der Elektrobranche nennt die 50 Stunden. Arbeit darüber hinaus ist Überzeit; sie ist nur ausnahmsweise und begrenzt zulässig und mit einem Lohnzuschlag von mindestens 25 Prozent zu entschädigen, sofern sie nicht im Einverständnis mit dem Arbeitnehmer durch Freizeit von gleicher Dauer ausgeglichen wird. Der GAV der Elektrobranche verlangt den Zuschlag zwingend in Geld, ausser es werden schon Zuschläge für Samstags-, Nacht-, Sonn- oder Feiertagsarbeit bezahlt.", abgrenzung: [{wort: "Überstunden", id: "ueberstunden", text: "Überstunden liegen über der vereinbarten, aber unter der gesetzlichen Höchstarbeitszeit."}], quellen: [{t: "Art. 9 Abs. 1 Bst. b ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_9"}, {t: "Art. 12 Abs. 1 und 2 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_12"}, {t: "Art. 13 Abs. 1 und 2 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_13"}, {t: "GAV Elektrobranche, Art. 22"}]},
    {id: "pause", wort: "Pause und Ruhezeit", formen: ["Pause", "Pausen", "Mittagspause", "Ruhezeit"], kurz: "Pausen unterbrechen die Arbeit und sind keine Arbeitszeit; die Ruhezeit liegt zwischen zwei Arbeitstagen.", bedeutung: "Das Arbeitsgesetz verlangt Pausen je nach Tagesarbeitszeit (eine Viertelstunde bei mehr als fünfeinhalb, eine halbe Stunde bei mehr als sieben, eine Stunde bei mehr als neun Stunden) und eine tägliche Ruhezeit von mindestens elf aufeinanderfolgenden Stunden. Nach dem GAV der Elektrobranche dauert die Mittagspause 60 Minuten, bei höchstens neun Stunden Arbeit nach Vereinbarung 30 Minuten; dazu kann je Halbtag eine unbezahlte Pause kommen.", abgrenzung: [{wort: "Wartezeit", id: "wartezeit", text: "Während der Wartezeit hält sich der Arbeitnehmer bereit; sie ist Arbeitszeit, die Pause nicht."}, {wort: "Unterbruch", text: "Der GAV nennt die Mittagspause auch Unterbruch; das Vertragswerk braucht das Wort nicht für Arbeitsausfälle."}], quellen: [{t: "Art. 15 Abs. 1 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_15"}, {t: "Art. 15a Abs. 1 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_15_a"}, {t: "GAV Elektrobranche, Art. 28"}]},
    {id: "wegzeit", wort: "Wegzeit", formen: ["Wegzeit", "Arbeitsweg", "Fahrt zwischen Baustellen"], kurz: "Zeit für den Weg zur und von der Arbeit; der Arbeitsweg von zu Hause ist keine Arbeitszeit, die Fahrt zwischen Baustellen schon.", bedeutung: "Der Weg zu und von der Arbeit gilt nach Arbeitsgesetz nicht als Arbeitszeit. Der GAV der Elektrobranche unterscheidet: Der Arbeitsweg vom Wohnort zum Betrieb ist keine Arbeitszeit; beginnt oder endet die Arbeit auswärts, gilt die Zeit, die diesen Arbeitsweg übersteigt, als Arbeitszeit, ausser innerhalb eines Rayons. Die Fahrt zwischen Baustellen während der Arbeit ist Arbeitszeit.", abgrenzung: [{wort: "Rayon", id: "rayon", text: "Im Rayon ist die Wegzeit im Ansatz enthalten, ausserhalb wird sie als Arbeitszeit in Rechnung gestellt."}, {wort: "Fahrzeit", id: "fahrzeit", text: "Fahrzeit misst nur die Dauer der Fahrt, mit der der Rayon bestimmt wird."}], quellen: [{t: "Art. 13 Abs. 1 ArGV 1", url: "https://www.fedlex.admin.ch/eli/cc/2000/243/de#art_13"}, {t: "GAV Elektrobranche, Art. 27.2 bis 27.4"}]},
    {id: "wartezeit", wort: "Wartezeit", formen: ["Wartezeit", "Wartezeit während der Arbeit"], kurz: "Zwei Bedeutungen: Zeit, in der der Arbeitnehmer bei der Arbeit bereitsteht; oder die Frist bis zum Taggeld der Unfallversicherung.", bedeutung: "Wartezeit während der Arbeit ist Teil der Arbeitszeit, in der der Arbeitnehmer bereitsteht, ohne arbeiten zu können, etwa weil Material fehlt. Im Versicherungsrecht ist Wartezeit die Zeit, bevor eine Versicherung leistet; das Taggeld der Unfallversicherung beginnt am dritten Tag nach dem Unfalltag.", abgrenzung: [{wort: "Aufschubzeit", id: "krankentaggeld", text: "Bei der Krankentaggeldversicherung heisst die Zeit bis zur Leistung nach GAV Aufschubzeit."}, {wort: "Pause", id: "pause", text: "Die Pause ist keine Arbeitszeit, die Wartezeit während der Arbeit schon."}], quellen: [{t: "Art. 13 Abs. 1 ArGV 1", url: "https://www.fedlex.admin.ch/eli/cc/2000/243/de#art_13"}, {t: "Art. 324b Abs. 3 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_324_b"}, {t: "Art. 16 Abs. 2 UVG", url: "https://www.fedlex.admin.ch/eli/cc/1982/1676_1676_1676/de#art_16"}]},
    {id: "arbeitstag", wort: "Arbeitstag", formen: ["Arbeitstag", "Arbeitstage", "Arbeitstagen"], kurz: "Ein Tag, an dem der Arbeitnehmer tatsächlich arbeitet.", bedeutung: "Im Vertragswerk jeder Tag, an dem der Arbeitnehmer beim Einsatzbetrieb arbeitet; ein Einsatz über Mitternacht zählt als ein Arbeitstag. Der GAV der Elektrobranche braucht das Wort auch als Einheit der Ferien.", abgrenzung: [{wort: "Werktag", id: "werktag", text: "Werktag ist eine Kalendereinheit (Montag bis Freitag ohne Feiertage), unabhängig davon, ob gearbeitet wird."}, {wort: "Kalendertag", text: "Fristen nach Tagen zählen nach OR jeden Tag des Kalenders."}], quellen: [{t: "GAV Elektrobranche, Art. 21.1 und 29.1"}]},
    {id: "werktag", wort: "Werktag", formen: ["Werktag", "Werktage", "Werktagen"], kurz: "Montag bis Freitag ohne die gesetzlichen Feiertage.", bedeutung: "Das Vertragswerk bestimmt den Werktag selbst: Montag bis Freitag ohne die öffentlichen Feiertage des Kantons. Fällt das Ende einer Frist auf einen Sonntag oder einen staatlich anerkannten Feiertag, endet sie nach OR am nächsten Werktag; die Gleichstellung des Samstags gilt von Gesetzes wegen nur für gesetzliche und behördliche Fristen, darum regelt der Vertrag sie selbst.", abgrenzung: [{wort: "Arbeitstag", id: "arbeitstag", text: "Am Werktag kann gearbeitet werden; Arbeitstag ist der Tag, an dem tatsächlich gearbeitet wird."}, {wort: "Feiertag", id: "feiertag", text: "Feiertage sind keine Werktage."}], quellen: [{t: "Art. 77 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_77"}, {t: "Art. 78 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_78"}, {t: "Art. 1 BG über den Fristenlauf an Samstagen (SR 173.110.3)"}]},
    {id: "feiertag", wort: "Feiertag", formen: ["Feiertag", "Feiertage", "Feiertagen"], kurz: "Gesetzlich anerkannter Ruhetag; der Bundesfeiertag und die kantonalen Feiertage.", bedeutung: "Der 1. August ist den Sonntagen gleichgestellt; die Kantone können höchstens acht weitere Feiertage im Jahr den Sonntagen gleichstellen. Im Kanton Bern bestimmt das Gesetz über die Ruhe an öffentlichen Feiertagen (BSG 555.1) die Feiertage. Der GAV der Elektrobranche entschädigt neun Feiertage im Jahr, sofern sie auf einen Arbeitstag fallen; Arbeit an Feiertagen trägt einen Zuschlag von 100 Prozent.", abgrenzung: [{wort: "Werktag", id: "werktag", text: "Feiertage zählen nicht als Werktage."}, {wort: "Ferien", id: "ferien", text: "Feiertage in den Ferien gelten nach GAV nicht als Ferientage."}], quellen: [{t: "Art. 20a Abs. 1 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_20_a"}, {t: "Art. 2 FRG Kanton Bern (BSG 555.1)"}, {t: "GAV Elektrobranche, Art. 25 und 30"}]},
    {id: "arbeit-auf-abruf", wort: "Arbeit auf Abruf", formen: ["Arbeit auf Abruf", "Abruf"], kurz: "Arbeitsform, bei der der Arbeitgeber die Arbeit nach Bedarf abruft; im Verleih nur eingeschränkt zulässig.", bedeutung: "Arbeitsform, bei der sich der Umfang der Arbeit nach dem Bedarf richtet, den der Arbeitgeber jeweils abruft. Die SECO-Weisungen lassen im Verleih Bandbreiten im Sinn echter Arbeit auf Abruf nur im Einzelfall zu und genehmigen keine Musterverträge mit unechter Arbeit auf Abruf, weil damit das Risiko fehlender Arbeit auf den Arbeitnehmer abgewälzt würde.", abgrenzung: [{wort: "Anfrage weiterer Tage", id: "vereinbarter-tag", text: "Nach dem Verleihvertrag fragt der Einsatzbetrieb weitere Tage an, und erst die Bestätigung des Verleihers macht sie verbindlich; das ist kein Abruf."}, {wort: "Annahmeverzug", id: "annahmeverzug", text: "Schickt der Einsatzbetrieb den Arbeitnehmer nach Hause, bleibt der Arbeitgeber gegenüber dem Arbeitnehmer lohnpflichtig."}], quellen: [{t: "SECO-Weisungen zum AVG, Ziff. 3.8.14"}, {t: "Art. 324 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_324"}]},
    {id: "arbeit-ohne-heimkehr", wort: "Arbeit ohne Heimkehr am Abend", formen: ["Arbeit ohne Heimkehr am Abend"], kurz: "Auswärtige Arbeit, nach der der Arbeitnehmer abends nicht nach Hause zurückkehrt; Unterkunft und Verpflegung kommen dazu.", bedeutung: "Längerdauernde auswärtige Arbeit, bei der der Arbeitnehmer am Abend nicht nach Hause zurückkehrt. Nach dem GAV der Elektrobranche hat er Anspruch auf Verpflegung und Unterkunft gegen Quittung, bei über einer Arbeitswoche auch auf die Heimreise übers Wochenende.", abgrenzung: [{wort: "Arbeit mit täglicher Rückkehr", text: "Liegt die Baustelle nur weiter weg, kehrt der Arbeitnehmer aber täglich heim, gilt der Ersatz der Mehrkosten für die Verpflegung (Art. 33.1 GAV)."}, {wort: "Montage", id: "montage", text: "Das Praxiswort Montage meint oft dasselbe, ist aber kein GAV-Begriff."}], quellen: [{t: "GAV Elektrobranche, Art. 33.2"}]},
    {id: "vereinbarter-tag", wort: "vereinbarter Tag", formen: ["vereinbarte Tage", "vereinbarten Tag", "vereinbarten Tage", "vereinbarten Tagen", "vereinbarten Werktag"], kurz: "Ein Tag, an dem nach dem Einsatzblatt oder nach Bestätigung des Verleihers gearbeitet werden soll.", bedeutung: "Werktag, für den das Einsatzblatt Stunden vorsieht, oder Tag, den der Verleiher auf Anfrage des Einsatzbetriebs per E-Mail bestätigt hat. Ferien und andere geplante Abwesenheiten des Arbeitnehmers sind keine vereinbarten Tage. Nur vereinbarte Tage können abgesagt werden oder einen Arbeitsausfall auslösen.", abgrenzung: [{wort: "Arbeitstag", id: "arbeitstag", text: "Am vereinbarten Tag soll gearbeitet werden; Arbeitstag ist er erst, wenn tatsächlich gearbeitet wird."}, {wort: "Arbeit auf Abruf", id: "arbeit-auf-abruf", text: "Weitere Tage entstehen nur durch Anfrage und Bestätigung, nicht durch einseitigen Abruf."}], quellen: [{t: "Wort des Vertragswerks, ohne Gesetzesgrundlage"}]},
    {id: "tagesminimum", wort: "Tagesminimum", formen: ["Tagesminimum", "Aufrundung auf das Tagesminimum"], kurz: "Mindestzahl Stunden, die für einen vereinbarten Werktag in Rechnung gestellt wird, auch wenn früher Schluss ist.", bedeutung: "Vertragliche Mindestzahl Stunden je Werktag, die der Verleiher in Rechnung stellt, wenn der Arbeitnehmer an diesem Tag arbeitet; die Werte je Wochentag stehen im Einsatzblatt. Die Differenz zwischen geleisteter Arbeitszeit und Tagesminimum heisst Aufrundung auf das Tagesminimum und trägt keinen Zuschlag. Das Tagesminimum ist eine Preisregel des Verleihvertrags; ein Gesetz schreibt es nicht vor.", abgrenzung: [{wort: "Zuschlag", id: "zuschlag", text: "Der Zuschlag gilt für besondere Arbeitszeiten und Überzeit; die Aufrundung ist kein Zuschlag."}, {wort: "Tagessatz", id: "tagessatz", text: "Ein Tagessatz ist ein fester Preis je Tag unabhängig von den Stunden; das Tagesminimum ist eine Untergrenze in Stunden."}], quellen: [{t: "Wort des Vertragswerks, ohne Gesetzesgrundlage"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.1.4 (Abrechnung nach Stunden)"}]},
    {id: "kosten-des-verleihs", wort: "Kosten des Verleihs", formen: ["Kosten des Verleihs"], kurz: "Alles, was der Einsatzbetrieb dem Verleiher für den Verleih bezahlt.", bedeutung: "Der Verleihvertrag muss die Kosten des Verleihs angeben, einschliesslich aller Sozialleistungen, Zulagen, Spesen und Nebenleistungen. Im Vertragswerk bestehen sie aus dem Ansatz je Stunde und den ausdrücklich genannten Zusätzen wie Zuschlägen, Wegzeit ausserhalb des Rayons und MWST.", abgrenzung: [{wort: "Lohn", id: "lohn", text: "Den Lohn zahlt der Verleiher dem Arbeitnehmer; die Kosten des Verleihs zahlt der Einsatzbetrieb dem Verleiher."}, {wort: "Ansatz", id: "ansatz", text: "Der Ansatz ist der Preis je Stunde, ein Teil der Kosten des Verleihs."}], quellen: [{t: "Art. 22 Abs. 1 Bst. f AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "SECO, Muster Verleihvertrag, Ziff. 4"}]},
    {id: "ansatz", wort: "Ansatz", formen: ["Ansatz", "Ansatzes"], kurz: "Preis je Stunde geleisteter Arbeitszeit, den der Einsatzbetrieb dem Verleiher bezahlt.", bedeutung: "Preis je Stunde geleisteter Arbeitszeit nach dem Einsatzblatt. Im Vertragswerk enthält er Lohn mit Sozialleistungen, Zulagen, Spesen und Nebenleistungen, Werkzeug und Grundausrüstung, die Weiterbildungs- und Vollzugskosten sowie Verwaltungsaufwand und Gewinn. Das Wort ist kein Gesetzeswort; das AVG verlangt nur, dass die Kosten des Verleihs im Vertrag stehen.", abgrenzung: [{wort: "Lohn", id: "lohn", text: "Der Ansatz ist ein Preis zwischen zwei Firmen, kein Lohn."}, {wort: "Stundensatz, Tarif", id: "stundensatz", text: "Andere Wörter für den Preis je Stunde."}], quellen: [{t: "Art. 22 Abs. 1 Bst. f und Abs. 4 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}]},
    {id: "zuschlag", wort: "Zuschlag", formen: ["Zuschlag", "Zuschläge"], kurz: "Aufpreis in Prozent auf den Ansatz für besondere Arbeitszeiten und Überzeit.", bedeutung: "Im Verleihvertrag ein Aufpreis auf den Ansatz für Arbeit zu besonderen Arbeitszeiten und für Überzeit; er folgt den Lohnzuschlägen, die der GAV dem Arbeitnehmer gewährt. Trifft mehr als ein Zuschlag zu, gilt nur der höchste.", abgrenzung: [{wort: "Lohnzuschlag", id: "lohnzuschlag", text: "Der Lohnzuschlag geht an den Arbeitnehmer; der Zuschlag im Verleihvertrag ist der Preis an den Einsatzbetrieb."}, {wort: "Zulagen", text: "Das AVG nennt Zulagen als Teil der Kosten des Verleihs; sie sind im Ansatz enthalten, die Zuschläge kommen dazu."}, {wort: "Aufrundung auf das Tagesminimum", id: "tagesminimum", text: "Die Aufrundung ist kein Zuschlag."}], quellen: [{t: "GAV Elektrobranche, Art. 22 und 25"}, {t: "Art. 22 Abs. 1 Bst. f AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}]},
    {id: "lohnzuschlag", wort: "Lohnzuschlag", formen: ["Lohnzuschlag", "Lohnzuschläge", "Lohnzuschlägen"], kurz: "Aufschlag in Prozent auf den Lohn für besondere Arbeitszeiten, Überzeit und bestimmte Überstunden.", bedeutung: "Prozentualer Aufschlag auf den Lohn. Nach dem GAV der Elektrobranche: Samstag 13 bis 23 Uhr 25 Prozent, Nacht 50 Prozent, Sonntag und Feiertage 100 Prozent, Überzeit 25 Prozent, Überstunden über 100 Stunden am Jahresende 25 Prozent. Das Arbeitsgesetz verlangt für Überzeit mindestens 25 Prozent.", abgrenzung: [{wort: "Zuschlag", id: "zuschlag", text: "Im Verleihvertrag ist der Zuschlag der Preisaufschlag an den Einsatzbetrieb."}, {wort: "Ausgleich durch Freizeit", text: "Zuschläge für besondere Arbeitszeiten können nach GAV nur in Geld ausgeglichen werden."}], quellen: [{t: "GAV Elektrobranche, Art. 21.3, 22 und 25"}, {t: "Art. 13 Abs. 1 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_13"}, {t: "Art. 48a Abs. 1 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_a"}]},
    {id: "spesen", wort: "Spesen", formen: ["Spesen"], kurz: "Ersatz der Auslagen, die durch die Arbeit entstehen, etwa für Verpflegung oder Fahrten; Spesen sind kein Lohn.", bedeutung: "Ersatz der Auslagen, die bei der Ausführung der Arbeit notwendig entstehen; der Arbeitgeber muss sie ersetzen. Der GAV der Elektrobranche gewährt namentlich mindestens CHF 18 je Tag als Ersatz der Mehrkosten für die Verpflegung, wenn der Arbeitsort mehr als effektiv 15 Minuten vom Firmendomizil entfernt liegt, und CHF 0.60 je Kilometer für das private Auto mit ausdrücklichem Einverständnis. Nach den SECO-Weisungen sind Weg und Verpflegung am festen Einsatzort in der Regel keine Spesen.", abgrenzung: [{wort: "Lohn", id: "lohn", text: "Spesen ersetzen Kosten und sind kein Lohn; als Lohn verkleidete Spesen wären AHV-pflichtig."}, {wort: "Auslagen", id: "auslagen", text: "Auslagen sind die Kosten selbst, Spesen ihr Ersatz."}], quellen: [{t: "Art. 327a Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_327_a"}, {t: "Art. 22 Abs. 1 Bst. f AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "GAV Elektrobranche, Art. 33 und 34"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.8.8"}]},
    {id: "lohn", wort: "Lohn", formen: ["Lohn", "Lohns", "Lohnes", "Monatslohn", "Monatslohns", "Mindestlohn", "Bruttolohn"], kurz: "Das Entgelt, das der Arbeitgeber dem Arbeitnehmer für die Arbeit schuldet.", bedeutung: "Der Arbeitgeber hat dem Arbeitnehmer den vereinbarten oder üblichen Lohn zu entrichten, in der Regel Ende jedes Monats, mit schriftlicher Abrechnung. Der Bruttolohn ist der Lohn vor den Abzügen für Sozialversicherungen, der Nettolohn der ausbezahlte Betrag. Der Mindestlohn ist der vom GAV für die Lohnklasse festgelegte Monatslohn; Spesen zählen nicht dazu.", abgrenzung: [{wort: "Kosten des Verleihs", id: "kosten-des-verleihs", text: "Was der Einsatzbetrieb dem Verleiher zahlt, ist kein Lohn."}, {wort: "Spesen", id: "spesen", text: "Spesen ersetzen Auslagen und gehören nicht zum Lohn."}, {wort: "massgebender Lohn", id: "massgebender-lohn", text: "Der massgebende Lohn ist die Grundlage der AHV-Beiträge und umfasst mehr als den Monatslohn."}], quellen: [{t: "Art. 322 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_322"}, {t: "Art. 323 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_323"}, {t: "Art. 323b OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_323_b"}, {t: "Art. 48a Abs. 1 Bst. a AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_a"}, {t: "GAV Elektrobranche, Art. 17"}]},
    {id: "dreizehnter-monatslohn", wort: "13. Monatslohn", formen: ["13. Monatslohn"], kurz: "Zusätzlicher Monatslohn je Jahr; nach GAV Elektro 100 Prozent des durchschnittlichen Monatslohns.", bedeutung: "Lohnbestandteil, der vertraglich oder durch GAV geschuldet ist. Nach dem GAV der Elektrobranche beträgt er 100 Prozent des durchschnittlichen Monatslohns des Kalenderjahres und wird spätestens im Dezember oder bei Beendigung ausbezahlt, bei unvollständigem Jahr anteilsmässig.", abgrenzung: [{wort: "Gratifikation", id: "gratifikation", text: "Die Gratifikation ist eine Sondervergütung, die vom Willen des Arbeitgebers abhängen kann; der 13. Monatslohn ist geschuldeter Lohn."}], quellen: [{t: "GAV Elektrobranche, Art. 18"}, {t: "Art. 48a Abs. 1 Bst. d AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_a"}]},
    {id: "massgebender-lohn", wort: "massgebender Lohn", formen: ["massgebender Lohn", "massgebenden Lohn"], kurz: "Der Lohn, auf dem die AHV-Beiträge berechnet werden.", bedeutung: "Als massgebender Lohn gilt jedes Entgelt für in unselbständiger Stellung auf bestimmte oder unbestimmte Zeit geleistete Arbeit. Er ist die Grundlage der Beiträge an AHV, IV, EO und Arbeitslosenversicherung.", abgrenzung: [{wort: "Bruttolohn", id: "lohn", text: "Der Bruttolohn auf der Lohnabrechnung ist in der Regel, aber nicht immer, gleich dem massgebenden Lohn."}, {wort: "Spesen", id: "spesen", text: "Echte Spesen gehören nicht zum massgebenden Lohn."}], quellen: [{t: "Art. 5 Abs. 2 AHVG", url: "https://www.fedlex.admin.ch/eli/cc/63/837_843_843/de#art_5"}]},
    {id: "mwst", wort: "Mehrwertsteuer", formen: ["Mehrwertsteuer", "MWST"], kurz: "Bundessteuer auf Lieferungen und Dienstleistungen; sie kommt zu den Preisen dazu.", bedeutung: "Allgemeine Verbrauchssteuer des Bundes, namentlich auf Leistungen, die steuerpflichtige Personen im Inland gegen Entgelt erbringen. Die Rechnung nennt den anwendbaren Steuersatz und den Steuerbetrag; schliesst der Preis die Steuer ein, genügt der Steuersatz.", abgrenzung: [{wort: "Lohnabzüge", text: "Abzüge für Sozialversicherungen betreffen den Lohn des Arbeitnehmers, die MWST den Preis an den Einsatzbetrieb."}], quellen: [{t: "Art. 1 Abs. 1 und 2 MWSTG", url: "https://www.fedlex.admin.ch/eli/cc/2009/615/de#art_1"}, {t: "Art. 26 Abs. 2 Bst. f MWSTG", url: "https://www.fedlex.admin.ch/eli/cc/2009/615/de#art_26"}]},
    {id: "ohne-abzug", wort: "ohne Abzug", formen: ["ohne Abzug"], kurz: "Der ganze Rechnungsbetrag ist zu bezahlen, ohne Skonto und ohne eigene Abzüge.", bedeutung: "Zahlungsbedingung: Der Rechnungsbetrag ist vollständig zu bezahlen; Skonto oder andere Abzüge durch den Einsatzbetrieb sind nicht vereinbart. Eine gesetzliche Begriffsbestimmung gibt es nicht.", abgrenzung: [{wort: "netto", id: "netto", text: "Netto ist mehrdeutig (ohne Abzug, nach Rabatt, ohne MWST); das Vertragswerk vermeidet es."}, {wort: "Verrechnung", id: "verrechnung", text: "Auch das Verrechnen mit Gegenforderungen schliesst der Verleihvertrag aus."}], quellen: [{t: "Wort des Vertragswerks"}]},
    {id: "faelligkeit", wort: "Fälligkeit", formen: ["Fälligkeit", "Fälligkeitsdatum", "fällig", "fällige", "Verfalltag"], kurz: "Ab der Fälligkeit kann die Zahlung verlangt werden; ist dafür ein Datum bestimmt, ist es ein Verfalltag.", bedeutung: "Fälligkeit ist der Zeitpunkt, ab dem der Gläubiger die Leistung fordern kann; ist nichts bestimmt, sofort. Ist für die Erfüllung ein bestimmter Tag verabredet (Verfalltag), kommt der Schuldner schon mit dessen Ablauf in Verzug, ohne Mahnung.", abgrenzung: [{wort: "Zahlungsverzug", id: "zahlungsverzug", text: "Fälligkeit allein bewirkt noch keinen Verzug; dafür braucht es eine Mahnung oder einen Verfalltag."}, {wort: "Zahlungsfrist", id: "mahnung", text: "Die Zahlungsfrist einer Mahnung läuft erst nach eingetretenem Verzug."}], quellen: [{t: "Art. 75 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_75"}, {t: "Art. 102 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_102"}]},
    {id: "zahlungsverzug", wort: "Zahlungsverzug", formen: ["Zahlungsverzug", "Verzug", "Verzugszins"], kurz: "Der Schuldner zahlt eine fällige Forderung nicht, obwohl er gemahnt wurde oder der Verfalltag verstrichen ist.", bedeutung: "Ist eine Verbindlichkeit fällig, wird der Schuldner durch Mahnung des Gläubigers in Verzug gesetzt; bei einem Verfalltag schon mit dessen Ablauf. Wer mit der Zahlung einer Geldschuld in Verzug ist, schuldet Verzugszinse von 5 Prozent im Jahr, auch wenn ein geringerer Zins vereinbart ist.", abgrenzung: [{wort: "Fälligkeit", id: "faelligkeit", text: "Fällig heisst: kann verlangt werden; in Verzug heisst: zu spät."}, {wort: "Konventionalstrafe", id: "konventionalstrafe", text: "Die Konventionalstrafe ist ein vertraglich vereinbarter Betrag; der Verzugszins gilt von Gesetzes wegen."}], quellen: [{t: "Art. 102 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_102"}, {t: "Art. 104 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_104"}]},
    {id: "mahnung", wort: "Mahnung", formen: ["Mahnung", "Mahnungen", "letzte Mahnung", "letzten Mahnung", "Zahlungserinnerung", "Zahlungsfrist"], kurz: "Aufforderung an den Schuldner, eine fällige Forderung zu bezahlen; das Vertragswerk kennt Zahlungserinnerung, Mahnung und letzte Mahnung.", bedeutung: "Die Mahnung ist die Aufforderung des Gläubigers an den Schuldner, eine fällige Leistung zu erbringen; sie setzt ihn in Verzug. Das OR kennt keine Mahnstufen; rechtlich kann schon eine Zahlungserinnerung Mahnung sein. Das Vertragswerk nennt die drei Stufen Zahlungserinnerung, Mahnung und letzte Mahnung; jede setzt eine Zahlungsfrist, die letzte kündigt die Betreibung an.", abgrenzung: [{wort: "Mahngebühr", id: "mahngebuehr", text: "Eine Gebühr für Mahnungen ist nur geschuldet, wenn der Vertrag sie mit einem bestimmten Betrag vorsieht."}, {wort: "Nachfrist", id: "nachfrist", text: "Die Nachfrist nach Art. 107 OR öffnet dem Gläubiger Wahlrechte bis zum Rücktritt vom Vertrag; die Zahlungsfrist einer Mahnung nicht."}, {wort: "Betreibung", id: "betreibung", text: "Die Betreibung ist das amtliche Verfahren, das nach erfolglosen Mahnungen folgen kann."}], quellen: [{t: "Art. 102 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_102"}]},
    {id: "konventionalstrafe", wort: "Konventionalstrafe", formen: ["Konventionalstrafe"], kurz: "Vertraglich vereinbarter Betrag, den eine Partei bei Nichterfüllung oder Verspätung zahlt, ohne dass ein Schaden bewiesen werden muss.", bedeutung: "Wird für den Fall der Nichterfüllung oder nicht richtigen Erfüllung eines Vertrags eine Konventionalstrafe versprochen, ist sie verfallen, auch wenn dem Gläubiger kein Schaden erwachsen ist. Übermässig hohe Konventionalstrafen hat der Richter nach seinem Ermessen herabzusetzen. Der Verleihvertrag sieht für Mahnungen eine solche Strafe mit festem Betrag vor.", abgrenzung: [{wort: "Verzugszins", id: "zahlungsverzug", text: "Der Verzugszins gilt von Gesetzes wegen, die Konventionalstrafe nur mit Vereinbarung."}, {wort: "Konventionalstrafe der paritätischen Organe", id: "paritaetische-organe", text: "Die paritätischen Organe können bei Verstössen gegen den GAV eine Konventionalstrafe nach GAV auferlegen; das ist eine andere Grundlage."}], quellen: [{t: "Art. 160 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_160"}, {t: "Art. 161 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_161"}, {t: "Art. 163 Abs. 3 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_163"}]},
    {id: "betreibung", wort: "Betreibung", formen: ["Betreibung", "Betreibungsbegehren"], kurz: "Amtliches Verfahren zur Eintreibung einer Geldforderung; es beginnt mit dem Betreibungsbegehren und dem Zahlungsbefehl.", bedeutung: "Zwangsvollstreckung einer Geldforderung durch das Betreibungsamt. Sie beginnt mit der Zustellung des Zahlungsbefehls, den das Amt auf das Betreibungsbegehren des Gläubigers erlässt. Der Schuldner kann innert zehn Tagen Rechtsvorschlag erheben; dann muss der Gläubiger die Forderung gerichtlich oder mit Rechtsöffnung durchsetzen.", abgrenzung: [{wort: "Mahnung", id: "mahnung", text: "Mahnungen sind private Aufforderungen; die Betreibung ist ein amtliches Verfahren."}, {wort: "Rechtsvorschlag", text: "Erklärung des Schuldners, mit der er die Forderung bestreitet und die Betreibung vorerst stoppt."}], quellen: [{t: "Art. 38 Abs. 2 SchKG", url: "https://www.fedlex.admin.ch/eli/cc/11/529_488_529/de#art_38"}, {t: "Art. 67 SchKG", url: "https://www.fedlex.admin.ch/eli/cc/11/529_488_529/de#art_67"}, {t: "Art. 69 SchKG", url: "https://www.fedlex.admin.ch/eli/cc/11/529_488_529/de#art_69"}, {t: "Art. 74 Abs. 1 SchKG", url: "https://www.fedlex.admin.ch/eli/cc/11/529_488_529/de#art_74"}, {t: "Art. 79 SchKG", url: "https://www.fedlex.admin.ch/eli/cc/11/529_488_529/de#art_79"}]},
    {id: "verrechnung", wort: "Verrechnung", formen: ["Verrechnung", "verrechnen", "Gegenforderung", "Gegenforderungen"], kurz: "Eine Schuld wird getilgt, indem der Schuldner eine eigene Gegenforderung abzieht.", bedeutung: "Schulden zwei Personen einander Geldsummen, kann jede ihre Forderung mit der Gegenforderung verrechnen, sofern beide fällig sind. Auf die Verrechnung kann der Schuldner zum Voraus verzichten. Im Verleihvertrag verzichtet der Einsatzbetrieb darauf; Einwendungen gegen den Wochenrapport bleiben möglich.", abgrenzung: [{wort: "in Rechnung stellen", text: "Umgangssprachlich heisst verrechnen auch in Rechnung stellen; das Vertragswerk braucht das Wort nur im Sinn des OR."}, {wort: "Aufrechnung", id: "aufrechnung", text: "Deutsches Wort für dieselbe Sache."}], quellen: [{t: "Art. 120 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_120"}, {t: "Art. 124 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_124"}, {t: "Art. 126 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_126"}]},
    {id: "abtretung", wort: "Abtretung", formen: ["Abtretung", "abtreten"], kurz: "Übertragung einer Forderung auf einen anderen Gläubiger.", bedeutung: "Der Gläubiger kann eine ihm zustehende Forderung ohne Einwilligung des Schuldners an einen andern abtreten, soweit nicht Gesetz, Vereinbarung oder Natur des Rechtsverhältnisses entgegenstehen. Die Abtretung bedarf der schriftlichen Form. Der Verleihvertrag schliesst sie ohne Zustimmung der anderen Partei aus.", abgrenzung: [{wort: "Inkasso", text: "Beauftragt ein Gläubiger ein Inkassobüro nur mit dem Eintreiben, bleibt er Gläubiger."}, {wort: "Zession", id: "zession", text: "Fachwort für die Abtretung."}], quellen: [{t: "Art. 164 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_164"}, {t: "Art. 165 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_165"}]},
    {id: "zurueckhalten", wort: "zurückhalten", formen: ["zurückhalten"], kurz: "Die eigene Leistung vorläufig nicht erbringen, solange die andere Partei nicht zahlt.", bedeutung: "Wer bei einem zweiseitigen Vertrag erfüllen soll, kann seine Leistung zurückhalten, bis die andere Partei erfüllt oder die Erfüllung anbietet; ist die andere Partei zahlungsunfähig geworden, bis die Gegenleistung sichergestellt ist. Der Verleihvertrag erlaubt dem Verleiher, die Arbeit an weiteren vereinbarten Tagen zurückzuhalten, solange eine fällige Rechnung offen ist.", abgrenzung: [{wort: "Kündigung", id: "kuendigung", text: "Zurückhalten unterbricht nur; die Kündigung beendet den Vertrag."}, {wort: "Ruhen des Einsatzes", id: "verhinderung", text: "Der Einsatz ruht bei Verhinderung des Arbeitnehmers und bei höherer Gewalt; dafür ist keine offene Rechnung nötig."}], quellen: [{t: "Art. 82 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_82"}, {t: "Art. 83 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_83"}]},
    {id: "einwendung", wort: "Einwendung", formen: ["Einwendung", "Einwendungen", "bestreiten", "bestrittenen"], kurz: "Widerspruch gegen den Wochenrapport oder eine Rechnungsposition, mit Angabe des Grundes.", bedeutung: "Erklärung, mit der der Einsatzbetrieb Angaben des Wochenrapports oder eine Position der Rechnung bestreitet. Der Verleihvertrag verlangt sie innert einer Frist per E-Mail, mit dem bestrittenen Arbeitstag und dem Grund; danach gilt der Rapport als anerkannt. Gesetzeswörter sind Einwendung und bestreiten.", abgrenzung: [{wort: "Rechtsvorschlag", text: "Der Rechtsvorschlag ist die Bestreitung im Betreibungsverfahren gegenüber dem Betreibungsamt."}, {wort: "Mängelrüge", text: "Die Mängelrüge gehört zum Werkvertrag; im Verleih gibt es kein Werk, das gerügt werden könnte."}], quellen: [{t: "Art. 120 Abs. 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_120"}, {t: "Art. 74 SchKG", url: "https://www.fedlex.admin.ch/eli/cc/11/529_488_529/de#art_74"}]},
    {id: "wochenrapport", wort: "Wochenrapport", formen: ["Wochenrapport", "Wochenrapports", "Wochenrapporte"], kurz: "Aufzeichnung der geleisteten Arbeitszeit einer Kalenderwoche; Grundlage der Rechnung.", bedeutung: "Rapport der Arbeitsstunden einer Kalenderwoche mit Beginn, Ende und Pausen je Arbeitstag, von der Kontaktperson unterzeichnet oder nach dem Verleihvertrag ohne Unterschrift zugestellt. Die SECO-Weisungen sprechen von Stunden- bzw. Arbeitsrapport. Wochenrapporte gehören auch zu den Verzeichnissen, die der Arbeitgeber nach Arbeitsgesetz führen muss.", abgrenzung: [{wort: "Lohnabrechnung", text: "Die Lohnabrechnung geht an den Arbeitnehmer; der Wochenrapport ist Grundlage der Rechnung an den Einsatzbetrieb."}, {wort: "Regierapport", id: "regiearbeit", text: "Im Bauwesen meint Regierapport den Rapport über Arbeiten, die nach Aufwand statt zum Festpreis abgerechnet werden."}], quellen: [{t: "SECO-Weisungen zum AVG, Ziff. 3.8.14.1"}, {t: "Art. 46 ArG", url: "https://www.fedlex.admin.ch/eli/cc/1966/57_57_57/de#art_46"}]},
    {id: "absage", wort: "Absage", formen: ["Absage", "absagen", "abgesagten", "abgesagter", "Verschiebung"], kurz: "Der Einsatzbetrieb teilt vorher mit, dass an vereinbarten Tagen nicht gearbeitet wird.", bedeutung: "Mitteilung des Einsatzbetriebs, dass an vereinbarten Tagen nicht gearbeitet wird, gleich aus welchem Grund. Eine Verschiebung ist eine Absage verbunden mit der Anfrage nach einem neuen Tag. Das Gesetz kennt beide Wörter nicht; die Regeln stehen im Verleihvertrag.", abgrenzung: [{wort: "Arbeitsausfall", id: "arbeitsausfall", text: "Ein Hindernis am Tag selbst ist ein Arbeitsausfall, keine Absage."}, {wort: "Kündigung", id: "kuendigung", text: "Die Absage betrifft einzelne Tage; die Kündigung beendet den Verleihvertrag."}, {wort: "Stornierung", id: "stornierung", text: "Einkaufswort für dieselbe Sache."}], quellen: [{t: "Wort des Vertragswerks, ohne Gesetzesgrundlage"}]},
    {id: "arbeitsausfall", wort: "Arbeitsausfall", formen: ["Arbeitsausfall", "Hindernis", "Hindernisses", "Hindernisse", "Ersatzarbeit"], kurz: "Der Arbeitnehmer kann an einem vereinbarten Tag wegen eines Hindernisses nicht oder nicht voll arbeiten.", bedeutung: "Vereinbarter Werktag, an dem der Arbeitnehmer wegen eines Hindernisses nicht oder nicht voll arbeiten kann. Hindernis ist nach dem Verleihvertrag jeder Umstand ausser höherer Gewalt, der weder in der Person des Arbeitnehmers noch beim Verleiher liegt, etwa fehlendes Material oder Wetter. Der Einsatzbetrieb kann im Rahmen der Art der Arbeit Ersatzarbeit zuweisen. Gegenüber dem Arbeitnehmer bleibt der Arbeitgeber lohnpflichtig.", abgrenzung: [{wort: "Verhinderung des Arbeitnehmers", id: "verhinderung", text: "Liegt der Grund in der Person des Arbeitnehmers (Krankheit, Unfall), ist es kein Arbeitsausfall."}, {wort: "höhere Gewalt", id: "hoehere-gewalt", text: "Aussergewöhnliche, unabwendbare Ereignisse von aussen sind keine Hindernisse im Sinn des Arbeitsausfalls."}, {wort: "Schlechtwetterentschädigung", id: "schlechtwetter", text: "Die Arbeitslosenversicherung entschädigt wetterbedingte Ausfälle nur in bestimmten Branchen."}], quellen: [{t: "Art. 42 AVIG", url: "https://www.fedlex.admin.ch/eli/cc/1982/2184_2184_2184/de#art_42"}, {t: "Art. 43 AVIG", url: "https://www.fedlex.admin.ch/eli/cc/1982/2184_2184_2184/de#art_43"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.8.22"}]},
    {id: "hoehere-gewalt", wort: "höhere Gewalt", formen: ["höhere Gewalt", "höherer Gewalt"], kurz: "Unvorhersehbares, aussergewöhnliches Ereignis von aussen, das sich nicht abwenden lässt.", bedeutung: "Unvorhersehbares, aussergewöhnliches Ereignis, das mit dem Betrieb nicht zusammenhängt und unabwendbar von aussen hereinbricht, etwa Krieg oder Naturkatastrophe. Das Gesetz definiert den Begriff nicht; die Formel stammt aus der Rechtsprechung des Bundesgerichts zur Haftpflicht.", abgrenzung: [{wort: "Hindernis", id: "arbeitsausfall", text: "Gewöhnliches Wetter, fehlendes Material oder ein Halt durch die Bauleitung sind Hindernisse, keine höhere Gewalt."}, {wort: "Zahlungspflicht", text: "Geldschulden bleiben nach dem Verleihvertrag auch bei höherer Gewalt bestehen."}], quellen: [{t: "BGE 102 Ib 257 E. 5"}]},
    {id: "annahmeverzug", wort: "Annahmeverzug", formen: ["Annahmeverzug"], kurz: "Der Arbeitgeber nimmt die angebotene Arbeit nicht an; er schuldet den Lohn trotzdem.", bedeutung: "Kann die Arbeit infolge Verschuldens des Arbeitgebers nicht geleistet werden oder kommt er aus anderen Gründen mit der Annahme der Arbeitsleistung in Verzug, bleibt er zur Entrichtung des Lohnes verpflichtet, ohne dass der Arbeitnehmer nachleisten muss. Bei der Leiharbeit trägt der Verleiher so das Risiko fehlender Einsätze.", abgrenzung: [{wort: "Arbeitsausfall", id: "arbeitsausfall", text: "Der Arbeitsausfall regelt, was der Einsatzbetrieb dem Verleiher zahlt; der Annahmeverzug, was der Arbeitgeber dem Arbeitnehmer schuldet."}, {wort: "Zahlungsverzug", id: "zahlungsverzug", text: "Beim Zahlungsverzug ist der Schuldner einer Geldleistung säumig, beim Annahmeverzug der Empfänger einer Leistung."}], quellen: [{t: "Art. 324 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_324"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.1.2.2"}]},
    {id: "verhinderung", wort: "Verhinderung des Arbeitnehmers", formen: ["Verhinderung des Arbeitnehmers", "Verhinderung", "verhindert"], kurz: "Der Arbeitnehmer kann aus Gründen in seiner Person nicht arbeiten, etwa wegen Krankheit oder Unfall.", bedeutung: "Der Arbeitnehmer wird aus Gründen, die in seiner Person liegen, wie Krankheit, Unfall, Erfüllung gesetzlicher Pflichten oder Ausübung eines öffentlichen Amtes, ohne sein Verschulden an der Arbeitsleistung verhindert. Der Arbeitgeber schuldet ihm dann für eine beschränkte Zeit den Lohn oder eine gleichwertige Versicherungsleistung. Im Verleihvertrag ruht in dieser Zeit der Einsatz.", abgrenzung: [{wort: "Arbeitsausfall", id: "arbeitsausfall", text: "Beim Arbeitsausfall liegt der Grund ausserhalb des Arbeitnehmers und des Verleihers."}, {wort: "Arbeitsunfähigkeit", id: "arbeitsunfaehigkeit", text: "Die Arbeitsunfähigkeit ist der gesundheitliche Grund einer Verhinderung."}], quellen: [{t: "Art. 324a Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_324_a"}, {t: "Art. 48a Abs. 1 Bst. f AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_a"}]},
    {id: "arbeitsunfaehigkeit", wort: "Arbeitsunfähigkeit", formen: ["Arbeitsunfähigkeit", "arbeitsunfähig"], kurz: "Volle oder teilweise Unfähigkeit, wegen der Gesundheit die bisherige Arbeit zu leisten; belegt durch ein Arztzeugnis.", bedeutung: "Arbeitsunfähigkeit ist die durch eine Beeinträchtigung der körperlichen, geistigen oder psychischen Gesundheit bedingte, volle oder teilweise Unfähigkeit, im bisherigen Beruf oder Aufgabenbereich zumutbare Arbeit zu leisten. Nach dem GAV der Elektrobranche ist sie ab dem dritten Krankheitstag mit einem Arztzeugnis nachzuweisen.", abgrenzung: [{wort: "Erwerbsunfähigkeit", text: "Erwerbsunfähigkeit betrifft den ganzen Arbeitsmarkt, nicht nur den bisherigen Beruf."}, {wort: "Verhinderung des Arbeitnehmers", id: "verhinderung", text: "Verhinderung ist der weitere Begriff; sie umfasst auch Gründe ohne Krankheit."}], quellen: [{t: "Art. 6 ATSG", url: "https://www.fedlex.admin.ch/eli/cc/2002/510/de#art_6"}, {t: "GAV Elektrobranche, Art. 37.5"}]},
    {id: "lohnfortzahlung", wort: "Lohnfortzahlung", formen: ["Lohnfortzahlung"], kurz: "Lohn, den der Arbeitgeber weiterzahlt, wenn der Arbeitnehmer ohne Verschulden verhindert ist.", bedeutung: "Pflicht des Arbeitgebers, bei unverschuldeter Verhinderung des Arbeitnehmers für eine beschränkte Zeit den Lohn zu entrichten. Eine schriftliche Abrede, ein Normalarbeitsvertrag oder ein GAV kann sie durch eine mindestens gleichwertige Versicherung ersetzen; der GAV der Elektrobranche sieht eine Krankentaggeldversicherung mit 80 Prozent des Lohns vor.", abgrenzung: [{wort: "Krankentaggeld", id: "krankentaggeld", text: "Das Taggeld zahlt die Versicherung, die Lohnfortzahlung der Arbeitgeber selbst."}, {wort: "Annahmeverzug", id: "annahmeverzug", text: "Beim Annahmeverzug kann der Arbeitnehmer arbeiten, der Arbeitgeber nimmt die Arbeit aber nicht an."}], quellen: [{t: "Art. 324a OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_324_a"}, {t: "Art. 48a Abs. 1 Bst. f AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_a"}, {t: "GAV Elektrobranche, Art. 36 und 38"}]},
    {id: "krankentaggeld", wort: "Krankentaggeld", formen: ["Krankentaggeld", "Krankentaggelds", "Krankentaggeldversicherung", "Taggeld", "Karenztag", "Aufschubzeit"], kurz: "Leistung einer Versicherung je Krankheitstag anstelle des Lohns; nach GAV Elektro 80 Prozent.", bedeutung: "Leistung der Krankentaggeldversicherung je Tag der Arbeitsunfähigkeit wegen Krankheit. Nach dem GAV der Elektrobranche beträgt sie 80 Prozent des Lohns; die Prämie tragen Arbeitgeber und Arbeitnehmer je zur Hälfte. Der erste Krankheitstag ist Karenztag und wird nicht bezahlt; schiebt die Versicherung ihre Leistung auf (Aufschubzeit), zahlt der Arbeitgeber in dieser Zeit 80 Prozent des Lohns.", abgrenzung: [{wort: "Lohnfortzahlung", id: "lohnfortzahlung", text: "Was der Arbeitgeber selbst zahlt, ist Lohn; das Taggeld der Versicherung nicht."}, {wort: "Wartezeit", id: "wartezeit", text: "Bei der Unfallversicherung heisst die Zeit bis zum Taggeld Wartezeit."}], quellen: [{t: "GAV Elektrobranche, Art. 37 und 38"}, {t: "Art. 48a Abs. 1 Bst. g AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_48_a"}, {t: "Art. 324b OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_324_b"}]},
    {id: "unfallversicherung", wort: "Berufsunfall und Nichtberufsunfall", formen: ["Berufsunfälle", "Nichtberufsunfälle", "Berufsunfallversicherung", "Unfallversicherung"], kurz: "Die obligatorische Unfallversicherung deckt Unfälle bei der Arbeit und in der Freizeit; die Prämien sind verschieden verteilt.", bedeutung: "Berufsunfälle sind Unfälle bei der Arbeit, die der Arbeitnehmer auf Anordnung oder im Interesse des Arbeitgebers ausführt; Nichtberufsunfälle sind alle anderen. Die Prämie der Berufsunfallversicherung trägt der Arbeitgeber, die der Nichtberufsunfallversicherung der Arbeitnehmer. Das Taggeld beginnt am dritten Tag nach dem Unfalltag.", abgrenzung: [{wort: "Betriebshaftpflichtversicherung", id: "betriebshaftpflichtversicherung", text: "Die Unfallversicherung deckt den verletzten Arbeitnehmer, die Haftpflichtversicherung Schäden, die Dritten zugefügt werden."}], quellen: [{t: "Art. 7 UVG", url: "https://www.fedlex.admin.ch/eli/cc/1982/1676_1676_1676/de#art_7"}, {t: "Art. 8 UVG", url: "https://www.fedlex.admin.ch/eli/cc/1982/1676_1676_1676/de#art_8"}, {t: "Art. 91 UVG", url: "https://www.fedlex.admin.ch/eli/cc/1982/1676_1676_1676/de#art_91"}, {t: "Art. 16 Abs. 2 UVG", url: "https://www.fedlex.admin.ch/eli/cc/1982/1676_1676_1676/de#art_16"}]},
    {id: "berufliche-vorsorge", wort: "berufliche Vorsorge", formen: ["berufliche Vorsorge", "beruflichen Vorsorge", "Vorsorgeeinrichtung"], kurz: "Zweite Säule: Versicherung für Alter, Tod und Invalidität über eine Vorsorgeeinrichtung.", bedeutung: "Versicherung für Alter, Tod und Invalidität nach BVG. Der Arbeitgeber muss sich einer Vorsorgeeinrichtung anschliessen; die Beiträge richten sich nach deren Reglement, und der Beitrag des Arbeitgebers muss mindestens gleich hoch sein wie die gesamten Beiträge aller seiner Arbeitnehmer.", abgrenzung: [{wort: "AHV", text: "Die AHV ist die erste Säule; die berufliche Vorsorge ergänzt sie."}, {wort: "Pensionskasse", id: "pensionskasse", text: "Umgangswort für die Vorsorgeeinrichtung."}], quellen: [{t: "Art. 11 Abs. 1 BVG", url: "https://www.fedlex.admin.ch/eli/cc/1983/797_797_797/de#art_11"}, {t: "Art. 66 Abs. 1 BVG", url: "https://www.fedlex.admin.ch/eli/cc/1983/797_797_797/de#art_66"}]},
    {id: "ferien", wort: "Ferien", formen: ["Ferien", "Ferienanspruch"], kurz: "Bezahlte Freizeit zur Erholung; nach GAV Elektro bis zum 50. Altersjahr 27 Arbeitstage im Jahr.", bedeutung: "Der Arbeitgeber hat dem Arbeitnehmer jedes Dienstjahr wenigstens vier Wochen Ferien zu gewähren, bis zum vollendeten 20. Altersjahr fünf Wochen. Der GAV der Elektrobranche gewährt bis zum vollendeten 50. Altersjahr 27 und danach 30 Arbeitstage. Während des Arbeitsverhältnisses dürfen Ferien nicht durch Geld abgegolten werden.", abgrenzung: [{wort: "Feiertag", id: "feiertag", text: "Feiertage in den Ferien zählen nach GAV nicht als Ferientage."}, {wort: "Absenzen", id: "absenzen", text: "Absenzen sind bezahlte Abwesenheiten aus bestimmten Anlässen, keine Ferien."}], quellen: [{t: "Art. 329a Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_329_a"}, {t: "Art. 329d Abs. 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_329_d"}, {t: "GAV Elektrobranche, Art. 29"}]},
    {id: "absenzen", wort: "Absenzen", formen: ["Absenzen", "Abwesenheiten"], kurz: "Bezahlte Abwesenheiten aus bestimmten Anlässen wie Heirat, Todesfall oder Umzug.", bedeutung: "Bezahlte Abwesenheiten aus den Gründen, die der GAV der Elektrobranche aufzählt (etwa Heirat, Todesfall, Umzug, Betreuung kranker Kinder). Daneben gewährt das OR Mutterschaftsurlaub, Urlaub des andern Elternteils und Urlaub für die Betreuung eines wegen Krankheit oder Unfall schwer beeinträchtigten Kindes, die über die Erwerbsersatzordnung entschädigt werden, sowie bezahlten Urlaub von höchstens drei Tagen je Ereignis für die Betreuung von Angehörigen; Militärdienst, Zivildienst und Zivilschutz entschädigt ebenfalls die EO.", abgrenzung: [{wort: "Ferien", id: "ferien", text: "Ferien dienen der Erholung und werden frei geplant; Absenzen sind an einen Anlass gebunden."}, {wort: "Vaterschaftsurlaub", text: "Das OR sagt Urlaub des andern Elternteils; der GAV braucht noch das ältere Wort."}], quellen: [{t: "GAV Elektrobranche, Art. 32 und 40"}, {t: "Art. 329f OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_329_f"}, {t: "Art. 329g OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_329_g"}, {t: "Art. 329h OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_329_h"}, {t: "Art. 329i OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_329_i"}, {t: "Art. 16b EOG", url: "https://www.fedlex.admin.ch/eli/cc/1952/1021_1046_1050/de#art_16_b"}]},
    {id: "schadloshaltung", wort: "Schadloshaltung", formen: ["Schadloshaltung", "schadlos"], kurz: "Eine Partei ersetzt der anderen einen Schaden vollständig, auch wenn Dritte Ansprüche stellen.", bedeutung: "Wer einen anderen schadlos hält, ersetzt ihm einen Schaden vollständig und übernimmt Ansprüche Dritter, die gegen ihn erhoben werden. Das OR braucht das Wort etwa beim Rücktritt vom Werkvertrag. Der Verleihvertrag verpflichtet den Einsatzbetrieb, Verleiher und Arbeitnehmer für Schäden aus der Arbeit schadlos zu halten; der Arbeitnehmer kann das als begünstigter Dritter selbst geltend machen.", abgrenzung: [{wort: "Rückgriff", id: "rueckgriff", text: "Rückgriff ist der Anspruch dessen, der gezahlt hat, gegen den, der den Schaden letztlich tragen soll."}, {wort: "Freistellung", id: "freistellung", text: "Im Schweizer Arbeitsrecht meint Freistellung etwas anderes."}], quellen: [{t: "Art. 377 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_377"}, {t: "Art. 112 Abs. 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_112"}]},
    {id: "rueckgriff", wort: "Rückgriff", formen: ["Rückgriff", "Rückgriffs"], kurz: "Anspruch dessen, der einen Schaden bezahlt hat, gegen einen anderen, der ihn ganz oder teilweise tragen soll.", bedeutung: "Haften mehrere für denselben Schaden, kann derjenige, der mehr bezahlt hat als seinen Anteil, auf die anderen zurückgreifen; das Gericht bestimmt den Umfang nach Würdigung der Umstände. Auch Versicherer nehmen nach einer Zahlung Rückgriff auf Haftpflichtige.", abgrenzung: [{wort: "Schadloshaltung", id: "schadloshaltung", text: "Mit der Schadloshaltung verspricht eine Partei im Voraus, den Schaden zu tragen, auch gegen Rückgriffe Dritter."}, {wort: "Regress", id: "regress", text: "Versicherungswort für dieselbe Sache."}], quellen: [{t: "Art. 50 Abs. 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_50"}, {t: "Art. 51 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_51"}]},
    {id: "absicht-grobe-fahrlaessigkeit", wort: "Absicht und grobe Fahrlässigkeit", formen: ["Absicht", "absichtlich", "grobe Fahrlässigkeit", "grober Fahrlässigkeit", "fahrlässig"], kurz: "Die schweren Formen des Verschuldens; eine Haftung dafür kann nicht im Voraus ausgeschlossen werden.", bedeutung: "Absicht: Der Schaden wird gewollt oder in Kauf genommen. Grobe Fahrlässigkeit: nach der Rechtsprechung die Missachtung elementarster Vorsichtsgebote, die jeder verständige Mensch in gleicher Lage beachtet hätte. Eine im Voraus getroffene Vereinbarung, wonach die Haftung für rechtswidrige Absicht oder grobe Fahrlässigkeit ausgeschlossen sein soll, ist nichtig. Der Arbeitnehmer haftet dem Arbeitgeber für Schaden, den er absichtlich oder fahrlässig zufügt, nach dem Mass der Sorgfalt, für die er einzustehen hat.", abgrenzung: [{wort: "leichte Fahrlässigkeit", text: "Für leichte Fahrlässigkeit darf die Haftung vertraglich ausgeschlossen werden; der Verleihvertrag weist solche Schäden dem Einsatzbetrieb zu."}, {wort: "Vorsatz", id: "vorsatz", text: "Das OR sagt Absicht; Vorsatz ist das Wort des Strafrechts."}], quellen: [{t: "Art. 100 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_100"}, {t: "Art. 321e OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_321_e"}]},
    {id: "betriebshaftpflichtversicherung", wort: "Betriebshaftpflichtversicherung", formen: ["Betriebshaftpflichtversicherung", "Betriebshaftpflicht"], kurz: "Versicherung eines Betriebs für Schäden, die er oder seine Leute Dritten verursachen.", bedeutung: "Versicherung, die die gesetzliche Haftpflicht eines Betriebs für Personen- und Sachschäden Dritter deckt, bis zur vereinbarten Versicherungssumme je Ereignis. Was gedeckt und was ausgeschlossen ist, bestimmen die Versicherungsbedingungen der jeweiligen Police; ein Gesetz legt den Inhalt nicht fest.", abgrenzung: [{wort: "Bearbeitungsschaden", id: "bearbeitungsschaden", text: "Schäden an Sachen, die bearbeitet werden, sind in vielen Policen ausgeschlossen oder nur mit Zusatz gedeckt."}, {wort: "Unfallversicherung", id: "unfallversicherung", text: "Die Unfallversicherung deckt den eigenen verletzten Arbeitnehmer, nicht Schäden Dritter."}], quellen: [{t: "Allgemeine Versicherungsbedingungen der Versicherer"}]},
    {id: "bearbeitungsschaden", wort: "Bearbeitungs- und Obhutsschaden", formen: ["Bearbeitungs- und Obhutsschäden", "Bearbeitungsschaden", "Obhutsschaden"], kurz: "Schaden an Sachen, an denen gearbeitet wird, oder an Sachen, die zur Aufbewahrung oder zum Gebrauch übernommen wurden.", bedeutung: "Versicherungsbegriffe: Bearbeitungsschaden ist ein Schaden an Sachen, die bearbeitet werden oder an oder mit denen gearbeitet wird; Obhutsschaden ein Schaden an Sachen, die zum Gebrauch, zur Bearbeitung oder Aufbewahrung übernommen wurden. Viele Betriebshaftpflichtpolicen schliessen sie aus oder decken sie nur begrenzt. Der Verleihvertrag weist ihre Versicherung dem Einsatzbetrieb zu.", abgrenzung: [{wort: "Schaden am Werk", text: "Mängel des hergestellten Werks sind ein Thema des Werkvertrags; im Verleih haftet der Verleiher nicht für das Ergebnis der Arbeit."}], quellen: [{t: "Allgemeine Versicherungsbedingungen der Versicherer (Betriebshaftpflicht)"}]},
    {id: "arbeitssicherheit", wort: "Arbeitssicherheit", formen: ["Arbeitssicherheit", "Gesundheitsschutz"], kurz: "Massnahmen gegen Berufsunfälle und Berufskrankheiten; im Verleih ist der Einsatzbetrieb dafür verantwortlich.", bedeutung: "Der Arbeitgeber muss alle Massnahmen treffen, die zur Verhütung von Berufsunfällen und Berufskrankheiten nötig sind. Ein Arbeitgeber, der in seinem Betrieb Arbeitskräfte beschäftigt, die er von einem anderen Arbeitgeber ausleiht, hat ihnen gegenüber hinsichtlich der Arbeitssicherheit die gleichen Pflichten wie gegenüber den eigenen Arbeitnehmern. Er instruiert sie und stellt sichere Arbeitsmittel.", abgrenzung: [{wort: "technische Aufsicht", id: "installationsbewilligung", text: "Die technische Aufsicht nach NIV betrifft die Sicherheit der Installation, die Arbeitssicherheit die Sicherheit der arbeitenden Person."}], quellen: [{t: "Art. 10 VUV", url: "https://www.fedlex.admin.ch/eli/cc/1983/1968_1968_1968/de#art_10"}, {t: "Art. 9 ArGV 3", url: "https://www.fedlex.admin.ch/eli/cc/1993/2553_2553_2553/de#art_9"}]},
    {id: "schutzausruestung", wort: "Schutzausrüstung", formen: ["Schutzausrüstung", "persönliche Schutzausrüstung", "persönliche Grundausrüstung", "einsatzbezogene Schutzausrüstung"], kurz: "Ausrüstung, die vor Unfall- und Gesundheitsgefahren schützt: Grundausrüstung bringt der Arbeitnehmer mit, Spezielles stellt der Einsatzbetrieb.", bedeutung: "Persönliche Schutzausrüstung (wie Schutzhelm, Schutzbrille, Gehörschutz, Schutzschuhe, Schutzhandschuhe) muss der Arbeitgeber zur Verfügung stellen, wo Unfall- und Gesundheitsgefahren nicht anders zu beseitigen sind. Das Vertragswerk teilt sie auf: Die persönliche Grundausrüstung bringt der Arbeitnehmer mit; die einsatzbezogene Schutzausrüstung, die eine bestimmte Arbeit oder Baustelle darüber hinaus verlangt, stellt der Einsatzbetrieb. Die Teilung folgt der Empfehlung des Branchenverbands suissetec.", abgrenzung: [{wort: "Arbeitskleidung", text: "Kleidung für die Arbeit ohne Schutzwirkung ist keine Schutzausrüstung."}, {wort: "Werkzeug", id: "werkzeug", text: "Werkzeug dient der Arbeit, nicht dem Schutz."}], quellen: [{t: "Art. 5 VUV", url: "https://www.fedlex.admin.ch/eli/cc/1983/1968_1968_1968/de#art_5"}, {t: "Art. 10 VUV", url: "https://www.fedlex.admin.ch/eli/cc/1983/1968_1968_1968/de#art_10"}, {t: "suissetec, Merkblatt Personalverleih und Temporärarbeit"}]},
    {id: "werkzeug", wort: "Werkzeug", formen: ["Werkzeug"], kurz: "Persönliches Handwerkzeug und Kleingeräte des Arbeitnehmers; Material und Grossgeräte stellt der Einsatzbetrieb.", bedeutung: "Im Vertragswerk das persönliche Handwerkzeug und die Kleingeräte des Arbeitnehmers. Stellt der Arbeitnehmer im Einverständnis mit dem Arbeitgeber selbst Geräte oder Material zur Verfügung, ist er dafür angemessen zu entschädigen, sofern nichts anderes verabredet oder üblich ist. Dass der Arbeitnehmer mit Werkzeug, Material oder Geräten des Einsatzbetriebs arbeitet, ist ein Merkmal des Verleihs.", abgrenzung: [{wort: "Betriebsmittel", id: "betriebsmittel", text: "Betriebsmittel gehören dem Arbeitgeber und stehen in seinem Inventar; Werkzeug ist das persönliche Werkzeug des Arbeitnehmers."}, {wort: "Material, Grossgeräte", text: "Material, Grossgeräte, Gerüste und Hebemittel stellt nach dem Verleihvertrag der Einsatzbetrieb."}], quellen: [{t: "Art. 327 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_327"}, {t: "Art. 26 Abs. 2 Bst. b AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_26"}]},
    {id: "betriebsmittel", wort: "Betriebsmittel", formen: ["Betriebsmittel", "Betriebsmittel-Inventar"], kurz: "Geräte des Arbeitgebers, mit denen er den Arbeitnehmer ausrüstet und die in seinem Inventar stehen.", bedeutung: "Arbeitsgeräte, mit denen der Arbeitgeber den Arbeitnehmer ausrüstet, namentlich Elektrowerkzeug, Messgeräte und Fahrzeuge; das Gesetz verpflichtet den Arbeitgeber, den Arbeitnehmer mit den nötigen Geräten auszurüsten, soweit nichts anderes verabredet ist. Der Arbeitnehmer hat sie fachgerecht zu bedienen und sorgfältig zu behandeln. Das Wort selbst ist kein Gesetzeswort; der Arbeitsvertrag bestimmt es über das Inventar.", abgrenzung: [{wort: "Werkzeug", id: "werkzeug", text: "Werkzeug ist das persönliche Werkzeug des Arbeitnehmers."}], quellen: [{t: "Art. 327 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_327"}, {t: "Art. 321a Abs. 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_321_a"}]},
    {id: "kuendigung", wort: "Kündigung", formen: ["Kündigung", "kündigen", "kündbar"], kurz: "Einseitige Erklärung, die einen unbefristeten Vertrag mit Ablauf einer Frist beendet.", bedeutung: "Einseitige Erklärung einer Partei, mit der sie ein Vertragsverhältnis auf einen bestimmten Zeitpunkt beendet; sie wird mit dem Zugang wirksam. Ein unbefristetes Arbeitsverhältnis kann jede Partei unter Einhaltung der Kündigungsfrist kündigen. Im Verleih steht die Kündigung des Arbeitsverhältnisses nur dem Verleiher zu, nicht dem Einsatzbetrieb; den Verleihvertrag können Verleiher und Einsatzbetrieb nach dessen Regeln kündigen.", abgrenzung: [{wort: "fristlose Kündigung", id: "fristlose-kuendigung", text: "Aus wichtigen Gründen kann ein Arbeitsverhältnis sofort aufgelöst werden."}, {wort: "Änderungskündigung", text: "Kündigung, verbunden mit dem Angebot eines neuen Vertrags zu geänderten Bedingungen."}, {wort: "Absage", id: "absage", text: "Die Absage betrifft einzelne Tage, nicht den ganzen Vertrag."}], quellen: [{t: "Art. 335 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_335"}, {t: "Art. 22 Abs. 1 Bst. d AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "SECO-Weisungen zum AVG, Ziff. 3.11.4"}]},
    {id: "kuendigungsfrist", wort: "Kündigungsfrist", formen: ["Kündigungsfrist", "Kündigungsfristen"], kurz: "Zeit zwischen dem Zugang der Kündigung und dem Ende des Vertrags.", bedeutung: "Nach OR kann ein unbefristetes Arbeitsverhältnis im ersten Dienstjahr mit einer Frist von einem Monat, im zweiten bis neunten mit zwei und danach mit drei Monaten je auf das Ende eines Monats gekündigt werden. Im Personalverleih gelten bei unbefristeten Einsätzen in den ersten sechs Monaten kürzere Mindestfristen: zwei Tage in den ersten drei Monaten, sieben Tage vom vierten bis sechsten Monat. Für den Verleihvertrag schreibt das Gesetz keine Mindestfrist vor; er muss aber Dauer oder Kündigungsfristen nennen.", abgrenzung: [{wort: "Probezeit", id: "probezeit", text: "In der Probezeit gilt nach OR eine Frist von sieben Tagen."}, {wort: "Sperrfrist", id: "sperrfrist", text: "Während einer Sperrfrist darf der Arbeitgeber gar nicht kündigen."}], quellen: [{t: "Art. 335c OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_335_c"}, {t: "Art. 19 Abs. 4 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_19"}, {t: "Art. 22 Abs. 1 Bst. d AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}]},
    {id: "fristlose-kuendigung", wort: "fristlose Kündigung", formen: ["fristlose Kündigung", "fristlos"], kurz: "Sofortige Auflösung des Arbeitsverhältnisses aus einem wichtigen Grund.", bedeutung: "Aus wichtigen Gründen können Arbeitgeber und Arbeitnehmer das Arbeitsverhältnis jederzeit fristlos auflösen. Wichtiger Grund ist jeder Umstand, bei dem der kündigenden Partei nach Treu und Glauben die Fortsetzung nicht mehr zuzumuten ist. Ohne wichtigen Grund schuldet der Arbeitgeber, was der Arbeitnehmer bis zum Ablauf der ordentlichen Frist verdient hätte.", abgrenzung: [{wort: "Kündigung", id: "kuendigung", text: "Die ordentliche Kündigung braucht keinen Grund, aber eine Frist."}, {wort: "sofortige Kündigung des Verleihvertrags", text: "Der Verleihvertrag sieht eine sofortige Kündigung bei offener Rechnung nach der letzten Mahnung vor; das ist eine vertragliche Regel, nicht Art. 337 OR."}], quellen: [{t: "Art. 337 Abs. 1 und 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_337"}, {t: "Art. 337c Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_337_c"}]},
    {id: "probezeit", wort: "Probezeit", formen: ["Probezeit"], kurz: "Die erste Zeit eines Arbeitsverhältnisses mit kurzer Kündigungsfrist; nach OR der erste Monat.", bedeutung: "Als Probezeit gilt der erste Monat eines Arbeitsverhältnisses; in ihr kann mit sieben Tagen Frist auf jeden Zeitpunkt gekündigt werden. Durch schriftliche Abrede, Normalarbeitsvertrag oder Gesamtarbeitsvertrag kann Abweichendes vereinbart werden; verlängert werden darf sie auf höchstens drei Monate.", abgrenzung: [{wort: "Kündigungsfrist im Verleih", id: "kuendigungsfrist", text: "Die kurzen Fristen von Art. 19 Abs. 4 AVG gelten im Verleih unabhängig von einer Probezeit."}], quellen: [{t: "Art. 335b Abs. 1 und 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_335_b"}]},
    {id: "sperrfrist", wort: "Sperrfrist", formen: ["Sperrfrist", "Sperrfristen"], kurz: "Zeit, in der der Arbeitgeber nicht kündigen darf, etwa bei Krankheit oder Militärdienst.", bedeutung: "Nach der Probezeit darf der Arbeitgeber während bestimmter Zeiten nicht kündigen, etwa während Militär- oder Zivildienst, bei unverschuldeter Arbeitsunfähigkeit wegen Krankheit oder Unfall (je nach Dienstjahr 30, 90 oder 180 Tage) und während der Schwangerschaft und 16 Wochen nach der Niederkunft. Eine Kündigung während der Sperrfrist ist nichtig; eine vorher ausgesprochene Frist wird unterbrochen.", abgrenzung: [{wort: "Kündigungsfrist", id: "kuendigungsfrist", text: "Die Kündigungsfrist ist die Zeit bis zum Ende, die Sperrfrist die Zeit, in der gar nicht gekündigt werden darf."}, {wort: "Kündigung zur Unzeit", text: "So heisst das OR die Kündigung während einer Sperrfrist."}], quellen: [{t: "Art. 336c Abs. 1 und 2 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_336_c"}]},
    {id: "befristet", wort: "befristet", formen: ["befristet", "unbefristet"], kurz: "Ein befristeter Vertrag endet ohne Kündigung an einem bestimmten Tag; ein unbefristeter erst durch Kündigung.", bedeutung: "Ein befristetes Arbeitsverhältnis endet ohne Kündigung mit Ablauf der vereinbarten Dauer. Ein unbefristetes Arbeitsverhältnis dauert, bis eine Partei kündigt. Nennt das Einsatzblatt ein Ende des Einsatzes, endet auch der Verleihvertrag an diesem Tag ohne Kündigung.", abgrenzung: [{wort: "Probezeit", id: "probezeit", text: "Das OR regelt die Probezeit beim unbefristeten Arbeitsverhältnis: Als Probezeit gilt der erste Monat, sofern nichts anderes vereinbart ist."}], quellen: [{t: "Art. 334 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_334"}, {t: "Art. 335 Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_335"}]},
    {id: "uebertritt", wort: "Übertritt", formen: ["Übertritt in ein direktes Arbeitsverhältnis", "Übertritt", "übertreten"], kurz: "Der Einsatzbetrieb stellt den bisher verliehenen Arbeitnehmer selbst an.", bedeutung: "Anstellung des Arbeitnehmers durch den Einsatzbetrieb nach dem Ende des Einsatzes. Vereinbarungen, die dies erschweren oder verunmöglichen, sind nichtig. Zulässig ist nur eine Entschädigung an den Verleiher, wenn der Einsatz weniger als drei Monate gedauert hat und der Arbeitnehmer weniger als drei Monate danach übertritt; sie ist begrenzt auf den Anteil für Verwaltungsaufwand und Gewinn eines dreimonatigen Einsatzes.", abgrenzung: [{wort: "Arbeitsvermittlung", id: "arbeitsvermittlung", text: "Der Übertritt ist keine Vermittlung; der Verleiher wird dafür nicht als Vermittler tätig."}, {wort: "Konkurrenzverbot", id: "konkurrenzverbot", text: "Ein Verbot, beim Einsatzbetrieb anzufangen, wäre nach AVG nichtig."}], quellen: [{t: "Art. 22 Abs. 2 bis 4 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}, {t: "Art. 19 Abs. 5 Bst. b AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_19"}]},
    {id: "treuepflicht", wort: "Sorgfalts- und Treuepflicht", formen: ["Treuepflicht", "Sorgfaltspflicht"], kurz: "Pflicht des Arbeitnehmers, sorgfältig zu arbeiten und die berechtigten Interessen des Arbeitgebers zu wahren.", bedeutung: "Der Arbeitnehmer hat die ihm übertragene Arbeit sorgfältig auszuführen und die berechtigten Interessen des Arbeitgebers in guten Treuen zu wahren. Während des Arbeitsverhältnisses darf er keine Arbeit gegen Entgelt für einen Dritten leisten, soweit er dadurch die Treuepflicht verletzt, namentlich den Arbeitgeber konkurrenziert. Der GAV der Elektrobranche verbietet Berufsarbeit für Dritte gegen Entgelt als Schwarzarbeit.", abgrenzung: [{wort: "Konkurrenzverbot", id: "konkurrenzverbot", text: "Die Treuepflicht gilt während des Arbeitsverhältnisses von selbst; ein Konkurrenzverbot für die Zeit danach muss schriftlich vereinbart werden."}, {wort: "Schwarzarbeit im Gesetz", text: "Das Bundesgesetz gegen die Schwarzarbeit meint Verstösse gegen Melde- und Bewilligungspflichten; der GAV meint unerlaubte Nebenarbeit."}], quellen: [{t: "Art. 321a OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_321_a"}, {t: "GAV Elektrobranche, Art. 14.3.1"}]},
    {id: "konkurrenzverbot", wort: "Konkurrenzverbot", formen: ["Konkurrenzverbot"], kurz: "Vereinbarung, mit der sich der Arbeitnehmer verpflichtet, den Arbeitgeber nach dem Ende nicht zu konkurrenzieren.", bedeutung: "Der handlungsfähige Arbeitnehmer kann sich schriftlich verpflichten, nach Beendigung des Arbeitsverhältnisses den Arbeitgeber nicht zu konkurrenzieren. Das Verbot ist nur verbindlich, wenn er Einblick in den Kundenkreis oder in Fabrikations- und Geschäftsgeheimnisse hatte und die Verwendung den Arbeitgeber erheblich schädigen könnte; es ist nach Ort, Zeit und Gegenstand zu begrenzen und darf nur unter besonderen Umständen drei Jahre überschreiten. Im Personalverleih sind Vereinbarungen nichtig, die den Übertritt des Arbeitnehmers in den Einsatzbetrieb erschweren, im Arbeitsvertrag wie im Verleihvertrag; zulässig ist nur eine begrenzte Entschädigung des Verleihers, wenn der Einsatz weniger als drei Monate gedauert hat und der Übertritt innert drei Monaten nach seinem Ende erfolgt.", abgrenzung: [{wort: "Treuepflicht", id: "treuepflicht", text: "Die Treuepflicht gilt während des Arbeitsverhältnisses ohne besondere Vereinbarung."}, {wort: "Konkurrenzverbot des Gesellschafters", text: "Gesellschafter und Geschäftsführer einer GmbH unterliegen eigenen Treue- und Konkurrenzpflichten aus dem Gesellschaftsrecht."}], quellen: [{t: "Art. 340 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_340"}, {t: "Art. 340a Abs. 1 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_340_a"}, {t: "Art. 812 Abs. 3 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_812"}, {t: "Art. 19 Abs. 5 Bst. b AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_19"}, {t: "Art. 22 Abs. 2 bis 4 AVG", url: "https://www.fedlex.admin.ch/eli/cc/1991/392_392_392/de#art_22"}]},
    {id: "geschaeftsgeheimnis", wort: "Geschäftsgeheimnis", formen: ["Geschäftsgeheimnis", "Geschäftsgeheimnisse", "Geheimhaltung"], kurz: "Geheime Tatsachen eines Betriebs, an deren Geheimhaltung er ein berechtigtes Interesse hat, etwa Preise, Pläne oder Kunden.", bedeutung: "Der Arbeitnehmer darf geheim zu haltende Tatsachen, namentlich Fabrikations- und Geschäftsgeheimnisse, von denen er im Dienst des Arbeitgebers Kenntnis erlangt, während des Arbeitsverhältnisses nicht verwerten und anderen nicht mitteilen; auch nach dessen Beendigung bleibt er verpflichtet, soweit es zur Wahrung der berechtigten Interessen des Arbeitgebers erforderlich ist. Der Verrat von Geschäftsgeheimnissen ist auf Antrag strafbar.", abgrenzung: [{wort: "Personendaten", id: "personendaten", text: "Personendaten schützt das Datenschutzgesetz, Geschäftsgeheimnisse das OR und das Strafrecht."}], quellen: [{t: "Art. 321a Abs. 4 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_321_a"}, {t: "Art. 162 StGB", url: "https://www.fedlex.admin.ch/eli/cc/54/757_781_799/de#art_162"}]},
    {id: "personendaten", wort: "Personendaten", formen: ["Personendaten", "bearbeiten", "bearbeitet", "bekannt gibt", "bekannt geben", "Bekanntgaben"], kurz: "Alle Angaben über eine bestimmte oder bestimmbare Person; ihr Bearbeiten und Bekanntgeben regelt das Datenschutzgesetz.", bedeutung: "Personendaten sind alle Angaben, die sich auf eine bestimmte oder bestimmbare natürliche Person beziehen. Bearbeiten ist jeder Umgang mit Personendaten, etwa Beschaffen, Speichern, Verwenden, Bekanntgeben oder Löschen; Bekanntgeben ist das Übermitteln oder Zugänglichmachen. Der Arbeitgeber darf Daten über den Arbeitnehmer nur bearbeiten, soweit sie seine Eignung für das Arbeitsverhältnis betreffen oder zur Durchführung des Arbeitsvertrags erforderlich sind; der Verleiher darf sie grundsätzlich nur mit schriftlicher, jederzeit widerruflicher Zustimmung des Arbeitnehmers bearbeiten, an interessierte Einsatzbetriebe mit einem besonderen Interesse aber auch ohne Zustimmung weitergeben.", abgrenzung: [{wort: "Geschäftsgeheimnis", id: "geschaeftsgeheimnis", text: "Geschäftsgeheimnisse betreffen den Betrieb, Personendaten Menschen."}], quellen: [{t: "Art. 5 Bst. a, d und e DSG", url: "https://www.fedlex.admin.ch/eli/cc/2022/491/de#art_5"}, {t: "Art. 328b OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_328_b"}, {t: "Art. 47 Abs. 1, 2 und 4 AVV", url: "https://www.fedlex.admin.ch/eli/cc/1991/408_408_408/de#art_47"}]},
    {id: "gerichtsstand", wort: "Gerichtsstand", formen: ["Gerichtsstand", "Gerichtsstände"], kurz: "Der Ort, an dem eine Partei verklagt werden kann.", bedeutung: "Ort des Gerichts, das für eine Klage örtlich zuständig ist. Für Klagen aus Arbeitsrecht ist das Gericht am Wohnsitz oder Sitz der beklagten Partei oder am Ort, an dem der Arbeitnehmer gewöhnlich arbeitet, zuständig; für Klagen gestützt auf das AVG zudem das Gericht am Ort der Geschäftsniederlassung des Verleihers. Der Arbeitnehmer kann darauf nicht zum Voraus verzichten. Unter Firmen, etwa im Verleihvertrag, können die Parteien einen Gerichtsstand vereinbaren.", abgrenzung: [{wort: "anwendbares Recht", text: "Der Gerichtsstand sagt, wo geklagt wird; das anwendbare Recht, nach welchem Recht entschieden wird."}], quellen: [{t: "Art. 17 ZPO", url: "https://www.fedlex.admin.ch/eli/cc/2010/262/de#art_17"}, {t: "Art. 34 ZPO", url: "https://www.fedlex.admin.ch/eli/cc/2010/262/de#art_34"}, {t: "Art. 35 Abs. 1 Bst. d ZPO", url: "https://www.fedlex.admin.ch/eli/cc/2010/262/de#art_35"}]},
    {id: "nichtig", wort: "nichtig", formen: ["nichtig"], kurz: "Von Anfang an ungültig, ohne dass es jemand anfechten muss.", bedeutung: "Ein Vertrag, der einen unmöglichen oder widerrechtlichen Inhalt hat oder gegen die guten Sitten verstösst, ist nichtig. Betrifft der Mangel nur einzelne Teile, sind nur diese nichtig, sofern nicht anzunehmen ist, dass der Vertrag ohne den nichtigen Teil überhaupt nicht geschlossen worden wäre.", abgrenzung: [{wort: "anfechtbar", text: "Ein anfechtbarer Vertrag gilt, bis eine Partei ihn wegen Irrtum, Täuschung oder Furcht anficht."}, {wort: "zwingendes Recht", id: "zwingendes-recht", text: "Wer gegen zwingendes Recht abweicht, riskiert die Nichtigkeit dieser Bestimmung."}], quellen: [{t: "Art. 20 OR", url: "https://www.fedlex.admin.ch/eli/cc/27/317_321_377/de#art_20"}]},
    {id: "arbeitnehmerueberlassung", wort: "Arbeitnehmerüberlassung", siehe: "personalverleih", text: "Wort des deutschen Rechts (AÜG); das Schweizer Recht sagt Personalverleih."},
    {id: "zeitarbeit", wort: "Zeitarbeit", siehe: "personalverleih", text: "Wort aus Deutschland und Österreich; in der Schweiz heisst die Sache Personalverleih, die Form mit einem Vertrag je Einsatz Temporärarbeit."},
    {id: "entleiher", wort: "Entleiher", siehe: "einsatzbetrieb", text: "Wort des deutschen Rechts; das AVG sagt Einsatzbetrieb."},
    {id: "einsatzfirma", wort: "Einsatzfirma", siehe: "einsatzbetrieb", text: "Praxiswort; das Gesetz sagt Einsatzbetrieb."},
    {id: "kunde", wort: "Kunde", siehe: "einsatzbetrieb", text: "Im Vertragswerk heisst die Vertragspartei des Verleihers Einsatzbetrieb; Kunden sind die Auftraggeber des Einsatzbetriebs."},
    {id: "verleihbetrieb", wort: "Verleihbetrieb", siehe: "verleiher", text: "Wort der SECO-Weisungen; das Gesetz sagt Verleiher."},
    {id: "personalvermittlung", wort: "Personalvermittlung", siehe: "arbeitsvermittlung", text: "Praxiswort; das Gesetz sagt Arbeitsvermittlung. Sie ist vom Personalverleih getrennt geregelt."},
    {id: "leiharbeitnehmer", wort: "Leiharbeitnehmer", siehe: "arbeitnehmer", text: "Wort der SECO-Weisungen; das Vertragswerk sagt verliehener Arbeitnehmer."},
    {id: "mitarbeiter", wort: "Mitarbeiter", siehe: "arbeitnehmer", text: "Im Vertragswerk heissen so nur die eigenen Angestellten des Einsatzbetriebs; der verliehene Arbeitnehmer heisst Arbeitnehmer."},
    {id: "rahmenarbeitsvertrag", wort: "Rahmenarbeitsvertrag", siehe: "einsatzvertrag", text: "Bei der Temporärarbeit regelt er die allgemeinen Bedingungen; erst der Einsatzvertrag setzt ihn in Kraft. Bei der Leiharbeit gibt es keinen."},
    {id: "regiearbeit", wort: "Regiearbeit", formen: ["Regiearbeit", "Regie"], siehe: "leiharbeit", text: "Praxiswort aus dem Bau- und Montagegewerbe; es bezeichnet die Abrechnung nach Aufwand, keine Rechtsform. Die SECO-Weisungen ordnen es der Leiharbeit zu."},
    {id: "subunternehmer", wort: "Subunternehmer", siehe: "werkvertrag", text: "Wer einen Auftrag oder Werkvertrag ganz oder teilweise selbständig übernimmt, ist Subunternehmer; dann liegt kein Personalverleih vor."},
    {id: "einzelarbeitsvertrag", wort: "Einzelarbeitsvertrag", formen: ["Einzelarbeitsvertrag"], siehe: "arbeitsvertrag", text: "Gesetzeswort des OR für den Arbeitsvertrag zwischen einem Arbeitgeber und einem Arbeitnehmer, im Gegensatz zum Gesamtarbeitsvertrag."},
    {id: "stundensatz", wort: "Stundensatz", siehe: "ansatz", text: "Auch Tarif oder Stundentarif; das Vertragswerk sagt Ansatz."},
    {id: "tagessatz", wort: "Tagessatz", siehe: "ansatz", text: "Fester Preis je Tag, wie ihn Einkaufsbedingungen mancher Einsatzbetriebe vorsehen; der Verleihvertrag rechnet nach Stunden mit einem Tagesminimum."},
    {id: "entgelt", wort: "Entgelt", siehe: "kosten-des-verleihs", text: "Das SECO-Muster sagt Entgelt für den Einsatz, andere Verträge Vergütung; das Gesetz sagt Kosten des Verleihs."},
    {id: "fahrzeit", wort: "Fahrzeit", formen: ["Fahrzeit"], siehe: "wegzeit", text: "Mit der Fahrzeit mit dem Auto wird der Rayon bestimmt; die Zeit für den Weg zur Arbeit heisst Wegzeit."},
    {id: "stundenrapport", wort: "Stundenrapport", siehe: "wochenrapport", text: "Auch Arbeitsrapport oder Arbeitszeitrapport; das Vertragswerk sagt Wochenrapport."},
    {id: "visum", wort: "Visum", siehe: "unterzeichnen", text: "Einkaufswort für das Abzeichnen eines Rapports; das Vertragswerk verlangt eine Unterschrift oder regelt die Zustellung ohne Unterschrift."},
    {id: "mehrarbeit", wort: "Mehrarbeit", siehe: "ueberstunden", text: "Auch Mehrstunden; je nach Lage sind es Überstunden oder Überzeit. Das Vertragswerk braucht die Wörter nicht."},
    {id: "mahngebuehr", wort: "Mahngebühr", siehe: "konventionalstrafe", text: "Eine Gebühr für Mahnungen schuldet der Schuldner nur, wenn der Vertrag sie mit bestimmtem Betrag vorsieht; das Vertragswerk nennt sie Konventionalstrafe."},
    {id: "nachfrist", wort: "Nachfrist", siehe: "mahnung", text: "Die Nachfrist nach Art. 107 OR eröffnet Wahlrechte bis zum Rücktritt; das Vertragswerk setzt in den Mahnungen eine Zahlungsfrist."},
    {id: "aufrechnung", wort: "Aufrechnung", siehe: "verrechnung", text: "Wort des deutschen Rechts; das OR sagt Verrechnung."},
    {id: "zession", wort: "Zession", siehe: "abtretung", text: "Fachwort für die Abtretung einer Forderung."},
    {id: "regress", wort: "Regress", siehe: "rueckgriff", text: "Versicherungswort; das OR sagt Rückgriff."},
    {id: "freistellung", wort: "Freistellung", siehe: "schadloshaltung", text: "Im Schweizer Arbeitsrecht meint Freistellung die Befreiung des Arbeitnehmers von der Arbeitspflicht; für die Übernahme eines Schadens sagt das Vertragswerk schadlos halten."},
    {id: "vorsatz", wort: "Vorsatz", siehe: "absicht-grobe-fahrlaessigkeit", text: "Wort des Strafrechts; das OR sagt Absicht."},
    {id: "stornierung", wort: "Stornierung", siehe: "absage", text: "Auch Annullierung; Einkaufswörter für die Absage vereinbarter Tage."},
    {id: "schlechtwetter", wort: "Schlechtwetter", siehe: "arbeitsausfall", text: "Die Schlechtwetterentschädigung der Arbeitslosenversicherung gilt nur in bestimmten Branchen; nach den Grundlagen des Vertragswerks nicht für die Elektroinstallation. Im Verleihvertrag ist Wetter ein Hindernis wie jedes andere."},
    {id: "festanstellung", wort: "Festanstellung", siehe: "uebertritt", text: "Auch Direktanstellung oder Übernahme; das Gesetz sagt übertreten."},
    {id: "kontrollrecht", wort: "Kontrollrecht", siehe: "weisungsrecht", text: "Manche Verträge sagen Weisungs- und Kontrollrecht; das Vertragswerk braucht nur Weisungsrecht."},
    {id: "einwilligung", wort: "Einwilligung", siehe: "zustimmung", text: "Wort des Datenschutzgesetzes für die Zustimmung der betroffenen Person."},
    {id: "psa", wort: "PSA", siehe: "schutzausruestung", text: "Abkürzung für persönliche Schutzausrüstung."},
    {id: "wettbewerbsverbot", wort: "Wettbewerbsverbot", siehe: "konkurrenzverbot", text: "Wort des deutschen Rechts; das OR sagt Konkurrenzverbot."},
    {id: "netto", wort: "netto", siehe: "ohne-abzug", text: "Netto ist mehrdeutig: ohne Abzug, nach Rabatt oder ohne MWST, beim Lohn nach den Sozialabzügen. Das Vertragswerk sagt jeweils, was gemeint ist."},
    {id: "auslagen", wort: "Auslagen", formen: ["Auslagen"], siehe: "spesen", text: "Wort des OR für die Kosten, die bei der Arbeit entstehen; ihr Ersatz heisst Spesen."},
    {id: "alleingesellschafter", wort: "Alleingesellschafter", formen: ["Alleingesellschafter"], siehe: "inhaber", text: "Praxiswort für den einzigen Gesellschafter; nach Art. 28 Abs. 2 AVV und der SECO-Weisung 2014/1 ist er Inhaber."},
    {id: "kantonale-stelle", wort: "kantonale Stelle", siehe: "bewilligung", text: "Die Verleihbewilligung erteilt das kantonale Arbeitsamt."},
    {id: "gratifikation", wort: "Gratifikation", siehe: "dreizehnter-monatslohn", text: "Sondervergütung nach Art. 322d OR, die vom Willen des Arbeitgebers abhängen kann; anders als der geschuldete 13. Monatslohn."},
    {id: "pensionskasse", wort: "Pensionskasse", siehe: "berufliche-vorsorge", text: "Umgangswort für die Vorsorgeeinrichtung der beruflichen Vorsorge."},
    {id: "montage", wort: "Montage", siehe: "arbeit-ohne-heimkehr", text: "Praxiswort für auswärtige Arbeit; der GAV sagt Arbeit ohne Heimkehr am Abend."}
  ];

  /* Anfangsbuchstabe für die Gruppierung (Umlaute zum Grundbuchstaben) */
  function buchstabe(w) {
    var c = w.charAt(0).toUpperCase();
    return {"Ä": "A", "Ö": "O", "Ü": "U"}[c] || c;
  }
  VW.lexikonSortiert = function () {
    return VW.BEGRIFFE.slice().sort(function (a, b) { return a.wort.localeCompare(b.wort, "de"); });
  };

  if (typeof document === "undefined") return;

  VW.lexikonBauen = function () {
    var ziel = document.getElementById("lex"), abc = document.getElementById("lex-abc"), suche = document.getElementById("lex-suche");
    if (!ziel) return;
    var L = VW.lexikonSortiert(), gruppen = {};
    ziel.textContent = "";
    L.forEach(function (e) {
      var bu = buchstabe(e.wort);
      if (!gruppen[bu]) {
        gruppen[bu] = document.createElement("div");
        var h = document.createElement("div"); h.className = "lbuchst"; h.id = "lex-" + bu; h.textContent = bu;
        gruppen[bu].appendChild(h); ziel.appendChild(gruppen[bu]);
      }
      var el = document.createElement("div"); el.className = "le" + (e.siehe ? " siehe" : ""); el.id = "b-" + e.id;
      el.setAttribute("data-such", (e.wort + " " + (e.formen || []).join(" ") + " " + (e.bedeutung || e.text || "")).toLowerCase());
      var h4 = document.createElement("h4"); h4.textContent = e.wort;
      el.appendChild(h4);
      if (e.siehe) {
        var z = VW.begriff(e.siehe), p0 = document.createElement("p");
        p0.appendChild(document.createTextNode("Siehe "));
        var a0 = document.createElement("a"); a0.className = "sv"; a0.href = "#begriff-" + e.siehe; a0.textContent = z ? z.wort : e.siehe;
        p0.appendChild(a0);
        if (e.text) p0.appendChild(document.createTextNode(". " + e.text));
        el.appendChild(p0);
      } else {
        var p = document.createElement("p"); p.textContent = e.bedeutung; el.appendChild(p);
        (e.abgrenzung || []).forEach(function (ab) {
          var pa = document.createElement("p"); pa.className = "abgr";
          pa.appendChild(document.createTextNode("Abgrenzung zu "));
          var b = document.createElement("b");
          if (ab.id) { var a1 = document.createElement("a"); a1.href = "#begriff-" + ab.id; a1.textContent = ab.wort; a1.style.color = "inherit"; b.appendChild(a1); }
          else b.textContent = ab.wort;
          pa.appendChild(b); pa.appendChild(document.createTextNode(": " + ab.text));
          el.appendChild(pa);
        });
      }
      if (e.quellen && e.quellen.length) {
        var q = document.createElement("p"); q.className = "q"; q.appendChild(document.createTextNode("Quelle: "));
        e.quellen.forEach(function (qq, i) {
          if (i) q.appendChild(document.createTextNode(" · "));
          if (qq.url) { var a = document.createElement("a"); a.href = qq.url; a.rel = "noopener"; a.target = "_blank"; a.textContent = qq.t; q.appendChild(a); }
          else q.appendChild(document.createTextNode(qq.t));
        });
        el.appendChild(q);
      }
      gruppen[bu].appendChild(el);
    });
    abc.textContent = "";
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").forEach(function (bu) {
      var x;
      if (gruppen[bu]) {
        x = document.createElement("a"); x.href = "#lex-" + bu; x.textContent = bu;
        x.addEventListener("click", function (ev) { ev.preventDefault(); document.getElementById("lex-" + bu).scrollIntoView({behavior: "smooth", block: "start"}); });
      } else { x = document.createElement("span"); x.textContent = bu; }
      abc.appendChild(x);
    });
    suche.addEventListener("input", function () {
      var t = suche.value.trim().toLowerCase();
      Object.keys(gruppen).forEach(function (bu) {
        var sichtbar = 0;
        Array.prototype.forEach.call(gruppen[bu].querySelectorAll(".le"), function (el) {
          var an = !t || el.getAttribute("data-such").indexOf(t) >= 0;
          el.hidden = !an; if (an) sichtbar++;
        });
        gruppen[bu].hidden = !sichtbar;
      });
    });
  };
})(typeof window !== "undefined" ? window : globalThis);
